INSERT INTO `ai_cache` (`id`, `user_id`, `question_text`, `answer_text`, `question_hash`, `mode`, `hits`, `last_used`) VALUES
(1, 3, 'parle moi de la faculte des sciences', 'La Faculté des Sciences (FS) de l\'Université de Douala est située sur le campus de PK17, qui abrite le Décanat, les salles de cours, les laboratoires et un amphithéâtre. Elle a été créée en 1993.\r\n\r\nElle propose des formations dans trois cycles d\'études : Licence (3 ans), Master (2 ans) et Doctorat.\r\n\r\nLa Faculté des Sciences est structurée en plusieurs départements, parmi lesquels on trouve:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n\r\nElle offre également des filières professionnelles en plus des formations initiales classiques. Les conditions d\'admission requièrent généralement un Baccalauréat scientifique (C, D, E, F, TI) ou un GCE avec au moins deux matières scientifiques.', '5f6be4410f1ea1272214d64cb0e505a4aa7d76c02bdc8bef9ab60f9d708a5394', 'informations', 1, '2026-03-25 10:13:49'),
(2, 3, 'comment faire les preinscriptions a la faculte des sciences?', 'Pour faire les pré-inscriptions à la Faculté des Sciences de l&#039;Université de Douala, voici les étapes à suivre :\r\n\r\n1.  **Conditions d&#039;admission** : Vous devez être titulaire d&#039;un Baccalauréat scientifique (C, D, E, F, T) ou d&#039;un GCE-AL obtenu avec au moins deux matières scientifiques.\r\n2.  **Pré-inscription en ligne** : La pré-inscription se fait uniquement sur étude de dossier via les plateformes en ligne.\r\n    *   Connectez-vous sur le site www.systhag-online.cm ou www.facscienceunivdouala.cm.\r\n    *   Un communiqué du Recteur de l&#039;Université annonce le début et la fin des pré-inscriptions sur www.systhag-online.cm.\r\n3.  **Paiement des frais de pré-inscription** :\r\n    *   Les frais de pré-inscription s&#039;élèvent à 10 000 (dix mille) francs CFA.\r\n    *   Le paiement se fait à UBA (United Bank for Africa), qui peut déployer des postes de paiement sur les campus.\r\n    *   Vous devrez également payer les frais de visite médicale et au moins la première tranche des droits universitaires.\r\n4.  **Dépôt des pièces du dossier en ligne** :\r\n    *   Connectez-vous à www.facsciences-online.cm pour déposer les pièces de votre dossier en ligne.\r\n    *   Les documents à scanner et importer (en format image lisible et ne dépassant pas 1 Mo) incluent : une photo portrait 4x4, une photocopie certifiée conforme de l&#039;acte de naissance, la fiche de pré-inscription signée, le certificat médical délivré par le centre médico-social de l&#039;Université de Douala, les photocopies certifiées conformes du probatoire (ou GCE OL) et du Baccalauréat (ou GCE AL), ainsi que les reçus et quitus de paiement des frais de pré-inscription et des droits universitaires.\r\n5.  **Téléchargement et impression** : Téléchargez et imprimez la fiche de pré-inscription et le quitus de paiement des frais de pré-inscription à l&#039;adresse www.systhag-online.cm.\r\n6.  **Validation de la candidature** : Après avoir importé tous les documents, cliquez sur &quot;valider&quot; pour enregistrer vos données.\r\n7.  **Affichage des listes** : Après l&#039;affichage des listes d&#039;étudiants pré-inscrits, vous devrez relever votre numéro de pré-inscription.\r\n8.  **Paiement des droits universitaires** : Téléchargez les quitus de paiement des deux tranches (DU) grâce à votre numéro de pré-inscription, puis payez la 1ère ou les deux tranches pour obtenir un numéro matricule unique.\r\n\r\nLes renseignements afférents sont disponibles à la scolarité de la Faculté dès le mois de Septembre de chaque année. Les pré-inscriptions pour l&#039;année académique 2025-2026 sont ouvertes tous les jours.', '516812b9b1770edb20b4d994f2f6a2ca660c8d0bc6400e0e8388c5d07640116d', 'informations', 1, '2026-03-20 13:22:56'),
(3, 3, 'ou est situe la faculte des sciences?', 'La Faculté des Sciences de l\'Université de Douala est située sur le campus de **PK17**.', 'd00b223cd3dc930270743f816002e04969602b8cc456aea6a9796fc9cf7d313d', 'informations', 1, '2026-03-25 10:14:07'),
(4, 3, 'quels sont les differents campus de cette faculte?', 'La Faculté des Sciences de l\'Université de Douala est principalement située sur le **campus de PK17**, où se trouvent le Décanat, les salles de cours, les laboratoires et un amphithéâtre.\r\n\r\nCependant, la Faculté des Sciences utilise également d\'autres sites de l\'Université de Douala :\r\n*   Elle dispose d\'un amphithéâtre au **campus I**, en face du gymnase.\r\n*   Certains de ses locaux, notamment ceux abritant le CEPAMOQ (Centre de Physique Atomique Moléculaire et Optique Quantique), se trouvent à l\'*ancien Rectorat à Akwa**.\r\n*   Elle partage des salles de cours Extension et deux amphithéâtres de 500 places avec d\'autres facultés de l\'Université de Douala au **campus II à Ndogbong**.', '0d42491dca2f504b5de692217dc17d32a5051dbee2f15aff50149d5da5f6d1ea', 'informations', 1, '2026-03-25 10:15:31'),
(5, 3, 'comment s&#039;inscrire à la faculté des sciences?', 'Pour s&#039;inscrire à la Faculté des Sciences de l&#039;Université de Douala, les nouveaux étudiants doivent suivre une procédure en plusieurs étapes, incluant la pré-inscription en ligne et la soumission d&#039;un dossier physique et numérique.\r\n\r\n**1. Conditions d&#039;admission au Niveau 1 :**\r\nPour être admissible, il faut être titulaire d&#039;un Baccalauréat scientifique (C, D, E, F, TI) ou d&#039;un GCE-AL obtenu avec au moins deux matières scientifiques (mathématiques, physique, chimie, biologie, informatique) et d&#039;un GCE-OL avec au moins deux matières scientifiques. Pour les filières Mathématiques et Informatique, un Baccalauréat C ou E est obligatoire ; si c&#039;est un Bac D, une moyenne d&#039;au moins 12/20 en Mathématiques est requise.\r\n\r\n**2. Étapes de la pré-inscription :**\r\n*   **Pré-inscription en ligne :** La pré-inscription se fait sur étude de dossier via les plateformes www.systhag-online.cm ou www.facscienceunivdouala.cm.\r\n*   **Dépôt des pièces en ligne :** Connectez-vous à www.facsciences-online.cm pour déposer les pièces de votre dossier en ligne.\r\n*   **Téléchargement et impression :** Téléchargez et imprimez la fiche de pré-inscription et le quitus de paiement des frais de pré-inscription depuis www.systhag-online.cm.\r\n*   **Paiement des frais de pré-inscription :** Payez les frais de pré-inscription d&#039;un montant de 10 000 FCFA à UBA (United Bank for Africa).\r\n*   **Paiement des frais de visite médicale :** Réglez les frais de visite médicale (5 000 FCFA) et effectuez la visite au centre médico-social de l&#039;Université de Douala.\r\n*   **Paiement des droits universitaires :** Réglez au moins la première tranche des droits universitaires (50 000 FCFA pour la première tranche).\r\n\r\n**3. Constitution et soumission du dossier :**\r\nAprès l&#039;affichage des listes des étudiants pré-inscrits, vous devrez :\r\n*   Relever votre numéro de pré-inscription.\r\n*   Télécharger les quitus de paiement des deux tranches des droits universitaires si nécessaire.\r\n*   Payer la 1ère ou les deux tranches pour obtenir un numéro matricule unique.\r\n\r\nLe dossier d&#039;inscription au Niveau 1 comprend généralement :\r\n*   Une fiche de pré-inscription dûment remplie.\r\n*   Une photocopie certifiée conforme du Baccalauréat/GCE-AL et du Probatoire/GCE-OL.\r\n*   Une photocopie certifiée conforme de l&#039;acte de naissance datant de moins de trois mois.\r\n*   Un certificat médical délivré par le Centre Médico-Social de l&#039;Université de Douala.\r\n*   Une photo d&#039;identité 4x4.\r\n*   Une enveloppe A4.\r\n*   Les photocopies certifiées des quitus et reçus de versement des frais de pré-inscription, de visite médicale et d&#039;au moins une tranche des frais d&#039;inscription.\r\n*   Une photocopie du reçu de paiement des frais d&#039;adhésion à l&#039;AE (1 000 FCFA).\r\n\r\nUne fois le dossier constitué, déposez une version numérique sur le site www.acad.fs-univ-dla.com', '04ea73addd500dc253e762f4a95a4d3bef201e30972220622306f2dcc0131afe', 'informations', 1, '2026-03-20 18:43:04'),
(6, 3, 'qui est le fondateur de la faculté des sciences de l&#039;université de douala?', 'La Faculté des Sciences de l&#039;Université de Douala n&#039;a pas un fondateur individuel désigné. Elle a été créée dans le cadre de la fondation de l&#039;Université de Douala par le décret présidentiel N° 93/030 du 19 janvier 1993. L&#039;Université de Douala elle-même est issue de la transformation du Centre universitaire de Douala, fondé le 28 avril 1977.', '492f2171b32af5c7f7acf8b786385f7ee52a020d689eef86ce7e6d9f22787714', 'informations', 1, '2026-03-23 15:37:16'),
(7, 3, 'd&#039;accord qui sont ses dirigeants?', 'La doyenne actuelle de la Faculté des Sciences de l&#039;Université de Douala est le Professeur Marie Joseph Ntamak.', 'a38a0ba9f94fb9b42eb0b153f61718024dac2b22b58fd2e731dcdbbc20f27099', 'informations', 1, '2026-03-23 15:38:05'),
(8, 3, 'par le moi de tout le corps administratif de la faculté des sciences', 'Le corps administratif de la Faculté des Sciences de l&#039;Université de Douala est dirigé par le Doyen.\r\n\r\nActuellement, la doyenne de la Faculté des Sciences de l&#039;Université de Douala est le **Professeur Marie Joseph Ntamak**.\r\n\r\nBien qu&#039;une liste exhaustive et à jour de tous les Vice-Doyens, du Secrétaire et des Chefs de Départements ne soit pas disponible dans les informations consultées, il est courant qu&#039;une faculté soit structurée comme suit :\r\n\r\n*   **Le Doyen** : Responsable de la direction générale de la faculté.\r\n*   **Les Vice-Doyens** : Généralement chargés de domaines spécifiques tels que la programmation et le suivi des activités académiques, la recherche et la coopération, ou encore la scolarité et le suivi des étudiants.\r\n*   **Le Secrétaire** (ou Secrétaire Principal/Administratif) : Assure la gestion administrative et la coordination des services.\r\n*   **Les Chefs de Départements** : Dirigent les différents départements d&#039;enseignement et de recherche au sein de la faculté (par exemple, Département de Physique, de Chimie, de Biologie, de Mathématiques, etc.).\r\n\r\nPour des informations plus détaillées et les nominations les plus récentes concernant l&#039;ensemble du corps administratif (Vice-Doyens, Secrétaire, Chefs de Départements), il serait recommandé de consulter le site web officiel de la Faculté des Sciences de l&#039;Université de Douala ou de contacter directement l&#039;administration de la faculté.', '7cff3ac20fcaf5281a51a8034df5daabd6c1b5ede0e132911185b42e066b3eff', 'informations', 1, '2026-03-23 15:39:17'),
(9, 3, 'parle moi de la faculté des sciences', 'La Faculté des Sciences (FS) de l&#039;Université de Douala, créée en 1993, est située sur le campus de PK17. Elle contribue à la mission globale de l&#039;Université de Douala, qui est l&#039;élaboration et la transmission des connaissances, le développement de la recherche et la formation des individus.\r\n\r\nLa Faculté des Sciences propose des formations réparties sur trois cycles : Licence, Master et Doctorat. Elle est structurée en plusieurs départements, notamment:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Mathématiques-Informatique\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nElle offre des filières de formation classiques et professionnelles, avec des spécialités variées en Chimie, Géosciences, Mathématiques, Informatique, Biologie et Physique. Les conditions d&#039;admission requièrent généralement un BAC C, D, E, F ou TI, ou un GCE &quot;AL&quot; avec au moins deux matières scientifiques, ainsi qu&#039;un GCE &quot;OL&quot; avec quatre matières dont au moins deux scientifiques (Mathématiques, Physique, Chimie, Biologie, Informatique).', 'b5ad37f3a079ad2b9896317548eed81023a77499bc60d615c13a27b578e66e31', 'informations', 1, '2026-03-23 15:51:42'),
(10, 3, 'bonsoir', 'Bonsoir ! Comment puis-je vous aider ce soir ?', 'ba10d93b0145b965543427ce81d8d6ee6a6269df7520d5082400996145ee4d2b', 'informations', 1, '2026-03-23 16:03:59'),
(11, 3, 'quels sont les enseignants de la faculté des    sciences?', 'Il n&#039;existe pas de liste publique exhaustive et constamment mise à jour de tous les enseignants de la Faculté des Sciences de l&#039;Université de Douala. Cependant, je peux vous donner des informations sur la structure de la faculté et des exemples de professeurs connus.\r\n\r\nLa Faculté des Sciences de l&#039;Université de Douala est organisée en plusieurs départements:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Le Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains professeurs de l&#039;Université de Douala sont mentionnés dans des documents publics, notamment dans des arrêtés de nomination ou des listes générales d&#039;enseignants-chercheurs. Par exemple, on peut citer :\r\n*   Monsieur YOMB Jacques, Maître de Conférences et Chef de Département.\r\n*   Monsieur MAPOURE NJANKOUO Yacouba, Professeur et Vice-Doyen chargé de la Programmation et du Suivi des Activités Académiques.\r\n*   Monsieur DOUMBE Jacques, Maître de Conférences et Chef de Département.\r\n*   Madame NGOUADJIEU Evelyne, Maître de Conférences.\r\n*   Annette Angoua Nguéa, Professeur.\r\n*   Assako Assako René Joly.\r\n*   Thomas Atenga.\r\n*   Samuel Bowong Tsakou.\r\n\r\nPour obtenir une liste plus précise et actuelle des enseignants par département, il serait préférable de consulter directement le site web officiel de la Faculté des Sciences de l&#039;Université de Douala (qui peut être fs-univdouala.ludovicathone.com ou fasciencedouala.com selon les sources) ou de contacter la scolarité de la Faculté.', '1a5c279bd14cffb49d3033e01b5d5edfad2c8c54717f3e9915eee402788e2009', 'informations', 1, '2026-03-23 16:06:02'),
(12, 3, 'quels sont les enseignants de la faculté des sciences?', 'En tant que fsAI, je peux vous informer que la Faculté des Sciences de l&#039;Université de Douala est structurée en plusieurs départements. Bien qu&#039;une liste exhaustive et à jour de tous les enseignants ne soit pas directement disponible via les recherches effectuées, voici les départements de la Faculté des Sciences:\r\n\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains noms d&#039;enseignants associés à l&#039;Université de Douala ont été mentionnés dans les résultats de recherche, tels que :\r\n\r\n*   Assako Assako René Joly\r\n*   Thomas Atenga\r\n*   Samuel Bowong Tsakou\r\n*   Annette Angoua Nguéa\r\n*   Monsieur YOMB Jacques (Maître de Conférences)\r\n*   Monsieur MAPOURE NJANKOUO Yacouba (Professeur)\r\n*   Madame ETOA, née ABOMO Marie Chantal (Professeur)\r\n*   Prisca Koncy Fosso (Maître Assistant)\r\n*   ELOUMOU BAGNAKA, Servais Albert Fiacre (Maître Assistant)\r\n*   Njoupouognigni, Moussa (Maître Assistant)\r\n*   ANABA EBANDA, Valéry Armel (Maître Assistant)\r\n*   DJIMEGNE EPOUSE KAMDEM, FELICITE (Maître Assistant)\r\n*   EBENDE KOUEDI, SANDRINE SARA (Maître Assistant)\r\n\r\nPour une liste complète et actualisée, il est recommandé de consulter directement le site web officiel de la Faculté des Sciences de l&#039;Université de Douala ou de contacter l&#039;administration de la faculté.', '64b6983e8107435f0731b83d31482ac75d4e5a41b0336c03364abc2210c4721e', 'informations', 1, '2026-03-23 16:07:39'),
(13, 3, 'quels sont les départements de la faculté des sciences?', 'Les départements de la Faculté des Sciences de l&#039;Université de Douala sont les suivants :\r\n\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)', '17b43627ed599de0e4e8e9dcc55f43af5abc70ceec8f6b1b1eacb02b615c8058', 'informations', 1, '2026-03-23 16:08:39'),
(14, 3, 'comment un étudiant peut faire pour aller faire un stage a l&#039;étranger quittant de la faculté des sciences en filiere informatique niveau master 2.', 'Pour qu&#039;un étudiant en Master 2 Informatique de la Faculté des Sciences de l&#039;Université de Douala puisse effectuer un stage à l&#039;étranger, voici les étapes et considérations clés :\r\n\r\n1.  **Définir le projet de stage** :\r\n    *   **Objectifs** : Préciser le type d&#039;expérience recherchée, les compétences à développer et le secteur d&#039;activité souhaité.\r\n    *   **Pays et durée** : Identifier les pays cibles et la durée du stage (souvent entre 2 et 12 mois pour les programmes internationaux).\r\n\r\n2.  **Contacter les services compétents de l&#039;Université** :\r\n    *   **Service des Relations Internationales** : Se rapprocher du service des relations internationales de l&#039;Université de Douala ou de la Faculté des Sciences. Ils pourront fournir des informations sur les partenariats existants, les programmes d&#039;échange et les procédures internes.\r\n    *   **Responsable de la filière** : Discuter du projet avec le responsable de la filière Informatique pour s&#039;assurer que le stage s&#039;inscrit bien dans le cursus et obtenir l&#039;accord pédagogique.\r\n\r\n3.  **Rechercher des opportunités de stage** :\r\n    *   **Programmes spécifiques** :\r\n        *   **IAESTE Cameroun** : Cette organisation facilite les stages techniques et scientifiques rémunérés à l&#039;international pour les étudiants camerounais. Les candidatures sont généralement ouvertes en février pour des offres reçues en janvier, mais des opportunités sont disponibles toute l&#039;année.\r\n        *   **Erasmus+** : Ce programme européen offre des bourses pour des stages en Europe. L&#039;étudiant doit être inscrit dans un établissement ayant une charte Erasmus+ et le stage doit être en rapport avec le diplôme préparé.\r\n    *   **Plateformes de recherche** : Consulter des sites spécialisés dans les offres de stages à l&#039;étranger ou les réseaux professionnels.\r\n    *   **Réseau personnel et académique** : Utiliser les contacts des professeurs, anciens élèves ou professionnels du domaine.\r\n\r\n4.  **Préparer le dossier de candidature** :\r\n    *   **Documents académiques** : Relevés de notes, CV, lettre de motivation, lettres de recommandation.\r\n    *   **Compétences linguistiques** : Souvent, un bon niveau dans la langue du pays d&#039;accueil (attesté par des tests comme le TOEFL, IELTS, DELF/DALF) est requis.\r\n    *   **Frais** : Certains programmes comme IAESTE Cameroun peuvent impliquer des frais d&#039;inscription et de participation.\r\n\r\n5.  **Aspects administratifs et financiers** :\r\n    *   **Convention de stage** : Une convention de stage est obligatoire et doit être établie entre l&#039;étudiant, l&#039;Université de Douala et l&#039;organisme d&#039;accueil à l&#039;étranger.\r\n    *   **Financement** : Les stages à l&#039;étranger sont souvent rémunérés, et des bourses peuvent être disponibles via les programmes (IAESTE, Erasmus+) ou les financeurs locaux et européens. Il est important de s&#039;assurer que la rémun', 'e25942590b8e2c2a85e758dd792b687ab1151e752cd130af470009e2ba13f32f', 'informations', 1, '2026-03-23 16:09:53'),
(15, 3, 'fait moi un racap des questions posees', 'Voici un récapitulatif des questions que vous avez posées :\r\n\r\n1.  &quot;Quels sont les enseignants de la Faculté des Sciences?&quot;\r\n2.  &quot;fait moi un racap des questions posees&quot; (la question actuelle)', '9136cb957c628f12e7e79d0e3e84e16d5d2de96ec4773b692aace01c5c6d943e', 'informations', 1, '2026-03-23 16:11:04'),
(16, 3, 'ok', 'D&#039;accord. Comment puis-je vous aider aujourd&#039;hui ?', '2689367b205c16ce32ed4200942b8b8b1e262dfc70d9bc9fbc77c49699a4f1df', 'informations', 1, '2026-03-24 12:50:49'),
(17, 3, 'quels sont les partenaires internationaux de la facultés des sciences de l&#039;université de douala?', 'La Faculté des Sciences de l&#039;Université de Douala participe à des collaborations internationales, notamment :\r\n\r\n*   **Projet EDU-ABCM :** La Faculté des Sciences est membre du projet EDU-ABCM, qui implique une collaboration avec des universités de quatre pays africains (Cameroun, Éthiopie, Maurice et Mozambique) et deux universités de l&#039;Union Européenne (Italie et Suède). Ce projet vise à moderniser les cours et programmes dans le secteur de l&#039;énergie.\r\n*   **Université Paris-Saclay (France) :** L&#039;Université de Douala a formalisé un partenariat avec l&#039;Université Paris-Saclay en 2019. Cette coopération universitaire globale inclut un accord spécifique avec l&#039;Université Paris-Sud (membre fondateur de l&#039;UPSaclay), qui se traduit par des programmes d&#039;échange avec diverses composantes des deux universités. Bien que la Faculté des Sciences ne soit pas explicitement nommée comme partenaire direct dans ces échanges spécifiques, elle fait partie de l&#039;Université de Douala qui bénéficie de ce partenariat global.', '5a4e1e12e3eef332c6033d07d74b101ba21933e2ad812f1945e05cf060cf93a7', 'informations', 1, '2026-03-24 12:51:39'),
(18, 3, 'quels sont ses differents campus?', 'L&#039;Université de Douala est une université multi-sites, répartie sur plusieurs campus dans la ville de Douala. La Faculté des Sciences est spécifiquement située sur le campus de **Ndogbong**.\r\n\r\nVoici les différents campus de l&#039;Université de Douala :\r\n*   **Campus Bassa (Cité Sic)** : Il s&#039;agit du campus principal, abritant l&#039;École Supérieure des Sciences Économiques et Commerciales (ESSEC), la Faculté des Sciences Juridiques et Commerciales, la Faculté des Sciences Économiques, la Faculté de Génie Industriel et la Faculté de Médecine.\r\n*   **Campus Ndogbong** : Ce campus accueille l&#039;Institut Universitaire de Technologie (IUT), l&#039;École Normale Supérieure d&#039;Enseignement Technique (ENSET), la **Faculté des Sciences (FS)**, la Faculté de Génie Industriel (FGI) et la Faculté de Médecine et des Sciences Pharmaceutiques (FMSP).\r\n*   **Campus Akwa** : Il abrite l&#039;École Doctorale, le Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ) et l&#039;Académie Internet.\r\n*   **Campus Nkongsamba** : Ce site loge l&#039;Institut des Beaux-Arts (IBA).\r\n*   **Campus Yabassi** : Il accueille l&#039;Institut des Sciences Halieutiques (ISH).\r\n*   **Campus Logbessou** : La construction de ce campus a débuté en 2011 et est destinée à la Faculté de Médecine et des Sciences Pharmaceutiques (FMSP) et à la Faculté de Génie Industriel (FGI).', 'a585c4f17e6d6f1c885245ce2783431ddf5dadbdefde250e56484d748acfc237', 'informations', 1, '2026-03-25 09:51:24'),
(19, 3, 'quels sont les enseignants de la facultés des sciences?', 'Il n&#039;existe pas de liste publique exhaustive et constamment mise à jour de tous les enseignants de la Faculté des Sciences de l&#039;Université de Douala.\r\n\r\nCependant, la Faculté des Sciences est organisée en plusieurs départements, et chaque département compte son propre corps enseignant. Pour obtenir une liste précise et actuelle des enseignants par département, il est recommandé de :\r\n\r\n*   **Consulter le site web officiel de la Faculté des Sciences de l&#039;Université de Douala.** Les sites web des facultés sont généralement les sources les plus fiables pour ce type d&#039;information.\r\n*   **Contacter directement la scolarité ou l&#039;administration de la Faculté des Sciences.** Ils pourront vous fournir les informations les plus à jour.\r\n\r\nJe peux vous donner des exemples de professeurs qui ont été mentionnés dans des documents publics ou des communications, mais cette liste n&#039;est pas exhaustive et peut ne pas être entièrement à jour :\r\n\r\n*   Monsieur YOMB Jacques (Maître de Conférences et Chef de Département)\r\n*   Monsieur MAPOURE NJANKOUO Yacouba (Professeur et Vice-Doyen chargé de la Programmation et du Suivi des Activités Académiques)\r\n*   Monsieur DOUMBE Jacques (Maître de Conférences et Chef de Département)\r\n*   Madame NGOUADJIEU Evelyne (Maître de Conférences)\r\n*   Annette Angoua Nguéa (Professeur)\r\n*   Assako Assako René Joly\r\n*   Thomas Atenga\r\n*   Samuel Bowong Tsakou\r\n\r\nPour des informations spécifiques sur les enseignants d&#039;un département particulier, je vous encourage vivement à vous référer aux canaux officiels de la Faculté.', 'ef158adbacd9fe8a4ca470285b301eda25496703bb65f4756ab655c3b01fc6fe', 'enseignants', 1, '2026-03-25 09:52:07'),
(20, 3, 'comment se passe les compositions au sein de la facultes de sciences?', 'Les compositions (examens) à la Faculté des Sciences de l&#039;Université de Douala se déroulent selon des modalités précises :\r\n\r\n*   **Conditions d&#039;accès aux salles d&#039;examen** : Pour être autorisé à composer, l&#039;étudiant doit impérativement avoir réglé au moins deux tranches des droits universitaires ou des frais de formation et présenter les reçus et quitus probants de ces paiements. Une photocopie de chaque quitus et reçu est souvent demandée par l&#039;équipe de contrôle.\r\n*   **Pièce d&#039;identité** : La présentation d&#039;une pièce d&#039;identification en cours de validité, portant la photo de l&#039;étudiant (comme le formulaire d&#039;inscription/réinscription téléchargé), est obligatoire.\r\n*   **Interdiction d&#039;appareils électroniques** : Les téléphones portables et tout autre dispositif électronique compromettant (comme les montres connectées) sont strictement interdits dans les salles d&#039;examen.\r\n*   **Unités d&#039;Enseignement (UE)** : Les étudiants composent uniquement sur les Unités d&#039;Enseignement (UE) qu&#039;ils ont sélectionnées lors de leur inscription académique pour le semestre en cours. Il n&#039;y a pas d&#039;examens pour les UE non sélectionnées.\r\n*   **Calendrier et listes** : Les examens de fin de semestre sont planifiés et un calendrier est communiqué aux étudiants. Des listes des étudiants autorisés à prendre part aux examens sont également publiées par domaine/parcours.\r\n*   **Périodicité** : Les examens ont lieu généralement à la fin de chaque semestre.', '6195a16c82c3899ff89435b44b6105901923be04e4a37e16eeedf753fc3e0123', 'cours', 1, '2026-03-25 09:52:54'),
(21, 3, 'quels sont les unites d&#039;enseignements pour les filieres informatiques niveau 1', 'Pour la filière Informatique de niveau 1 (Licence 1) à la Faculté des Sciences de l&#039;Université de Douala, les Unités d&#039;Enseignement (UE) comprennent des matières fondamentales, complémentaires et optionnelles.\r\n\r\nVoici une liste des UE généralement proposées:\r\n\r\n**Unités d&#039;Enseignement Fondamentales :**\r\n*   Introduction à l&#039;algorithme (INF 111)\r\n*   Architecture des ordinateurs (INF 121)\r\n*   Programmation structurée (C ou Python) (INF 131)\r\n*   Analyse 1 : analyse de la droite vectorielle réelle (MAT 121)\r\n*   Introduction à la programmation fonctionnelle (INF 112)\r\n*   Introduction aux réseaux (INF 122)\r\n*   Introduction aux systèmes d&#039;exploitation (INF 132)\r\n*   Algèbre linéaire (MAT 112)\r\n\r\n**Unités d&#039;Enseignement Complémentaires :**\r\n*   Éducation civique et éthique (INF 141)\r\n*   Formation bilingue 1 (INF 142)\r\n\r\n**Unités d&#039;Enseignement Optionnelles (au choix) :**\r\n*   Électrostatique (INF 151)\r\n*   Introduction au droit (INF 161)\r\n*   Programmation web statique (INF 171)\r\n*   Électronique numérique (INF 152)\r\n*   Programmation C++ (INF 162)\r\n*   Mécanique du point (INF 172)\r\n\r\nChaque UE a un nombre de crédits associé, généralement 6 pour les fondamentales et 3 pour les complémentaires et optionnelles.', 'd0f0f6dc4f1db7971d65304b3baa0513615a0c6c8c17d1d64d4646d5ff424a10', 'cours', 1, '2026-03-25 09:53:49'),
(22, 3, 'comment faire pour valider une matière dans cette facultés?', 'Pour valider une matière (Unité d&#039;Enseignement - UE) à la Faculté des Sciences de l&#039;Université de Douala, vous devez généralement remplir les conditions suivantes :\r\n\r\n1.  **Obtenir la moyenne requise :** La validation d&#039;une UE se fait généralement en obtenant une moyenne minimale de **10/20** (dix sur vingt) sur l&#039;ensemble des évaluations de cette UE. Cette moyenne prend en compte les différentes composantes de l&#039;évaluation.\r\n\r\n2.  **Composantes de l&#039;évaluation :** La note finale d&#039;une UE est souvent une combinaison de plusieurs éléments :\r\n    *   **Contrôles Continus (CC) :** Il s&#039;agit d&#039;évaluations effectuées pendant le semestre (interrogations, devoirs, exposés, travaux pratiques, projets, etc.). Ils comptent généralement pour un certain pourcentage de la note finale (par exemple, 30% ou 40%).\r\n    *   **Examen Final (EF) :** C&#039;est l&#039;épreuve principale qui a lieu à la fin du semestre. Elle compte pour le pourcentage restant de la note finale (par exemple, 60% ou 70%).\r\n\r\n    La formule de calcul de la note finale est généralement : **Note Finale = (Poids CC x Note CC) + (Poids EF x Note EF)**.\r\n\r\n3.  **Rattrapages (Seconde Session) :** Si vous n&#039;atteignez pas la moyenne de 10/20 à l&#039;issue de la première session d&#039;examen pour une UE, vous avez généralement droit à une **seconde session (rattrapage)**. Pour cette seconde session, seule la note de l&#039;examen final est généralement prise en compte pour le calcul de la nouvelle moyenne de l&#039;UE. Si vous validez l&#039;UE au rattrapage, la note maximale qui peut être attribuée est souvent plafonnée à 10/20, même si vous obtenez une note supérieure.\r\n\r\n4.  **Compensation :** Dans le système LMD (Licence, Master, Doctorat), il existe souvent un mécanisme de **compensation** entre les Unités d&#039;Enseignement au sein d&#039;un même semestre, ou parfois entre semestres. Cela signifie que si vous avez une note légèrement inférieure à 10/20 dans une UE, mais que vous avez de très bonnes notes dans d&#039;autres UE du même semestre, la moyenne générale du semestre peut vous permettre de valider l&#039;UE en question, même si sa note individuelle est inférieure à 10/20. Les règles de compensation sont spécifiques à chaque établissement et sont définies dans le règlement pédagogique.\r\n\r\nIl est crucial de consulter le **règlement pédagogique** de la Faculté des Sciences pour connaître les modalités exactes de validation des UE, les coefficients des différentes évaluations et les règles de compensation spécifiques à votre filière et à votre année d&#039;étude.', '1d85024785c8915e3f1453d0ce62a29811e76223d49dd958d40d456a1d693d2d', 'cours', 1, '2026-03-25 09:55:13'),
(23, 3, 'quels sont les laboratoires de cette facultes?', 'La Faculté des Sciences de l&#039;Université de Douala abrite plusieurs laboratoires de recherche. Voici quelques-uns d&#039;entre eux :\r\n\r\n*   **Laboratoire de Biologie et Physiologie Animale**\r\n*   **Laboratoire d&#039;Informatique Appliquée (LIA)** : Ce laboratoire est un centre de recherche multidisciplinaire dédié à l&#039;étude et au développement de solutions innovantes en informatique. Il est organisé autour d&#039;équipes de recherche telles que l&#039;équipe ISDM (Intelligent &amp; Sustainable Decision Making) et l&#039;équipe d&#039;imagerie et signal.\r\n*   **Laboratoire des Géosciences, ressources…**\r\n*   **CEPAMOQ (Centre de Physique Atomique Moléculaire et Optique Quantique)**\r\n*   **LTSA (Laboratoire de Traitement du Signal et des Applications)** : Créé en 2017, ce laboratoire de recherche appartient à l&#039;Unité de Formation Doctorale des Sciences Appliquées (UFD-SCA) de l&#039;École Doctorale des Sciences Fondamentales et Appliquées (EDOSFA) de l&#039;Université de Douala.', '7c2de2991343f40abc27e320a9c7d17a842e87fdb4a48dbed35f918ac8f0f1b8', 'informations', 1, '2026-03-25 09:56:43'),
(24, 3, 'tu connais le laboratoire isdm de pr. moskolai dans la facultes des sciences?', 'Oui, je connais le laboratoire ISDM et le Professeur Justin Moskolaï Ngossaha.\r\n\r\nL&#039;équipe **ISDM (Intelligent &amp; Sustainable Decision Making)** est une équipe de recherche interdisciplinaire rattachée au **Laboratoire d&#039;Informatique Appliquée (LIA)** du Département de Mathématiques et Informatique de la Faculté des Sciences de l&#039;Université de Douala.\r\n\r\nLe **Professeur Justin MOSKOLAI NGOSSAHA** est le **Coordinateur de l&#039;équipe de recherche ISDM**. Il est Maître de Conférences et chercheur au Département de Mathématiques et Informatique de la Faculté des Sciences de l&#039;Université de Douala. Ses activités de recherche se concentrent sur l&#039;intelligence artificielle, les systèmes d&#039;aide à la décision, l&#039;interopérabilité, l&#039;ingénierie des connaissances, les systèmes de transport et les systèmes durables.', '7a81d878c2c46c5c56cbff0182d094afc87473f24daba65e0347033f07f742ea', 'informations', 1, '2026-03-25 09:57:25'),
(25, 3, 'qui gere l&#039;equipe d&#039;imagerie et signal?', 'L&#039;équipe d&#039;imagerie et signal au sein du Laboratoire d&#039;Informatique Appliquée (LIA) de la Faculté des Sciences de l&#039;Université de Douala est supervisée par le **Dr. Joseph MVOGO NGONO**.', '1edfca9489bd2459cdac08678bcae56053fd38fbab84c18d7875321ad7d7bac9', 'informations', 1, '2026-03-25 09:58:51'),
(26, 3, 'et dr noumsi appartient a quel equipe?', 'Le Dr Vigny NOUMSI WOGUIA est l&#039;un des **Directeurs du Laboratoire d&#039;Informatique Appliquée (LIA)** à la Faculté des Sciences de l&#039;Université de Douala.\r\n\r\nLe LIA est le laboratoire qui abrite les équipes de recherche ISDM et l&#039;équipe d&#039;imagerie et signal.', '9f8a51ffa4cddebc4613461cabd5246824968bd87a74a2e037ba95b8b7d92f7e', 'informations', 1, '2026-03-25 09:59:12'),
(27, 3, 'parle moi de pr. justin moskolai, je veux une description complete', 'Le Professeur Justin Moskolaï Ngossaha est une figure éminente de la Faculté des Sciences de l&#039;Université de Douala, reconnu pour ses contributions significatives dans le domaine de l&#039;informatique et des systèmes d&#039;aide à la décision.\r\n\r\nVoici une description complète de son profil :\r\n\r\n**Position Actuelle et Affiliation :**\r\nLe Professeur Justin Moskolaï Ngossaha est **Maître de Conférences** et chercheur au **Département de Mathématiques et Informatique** de la Faculté des Sciences de l&#039;Université de Douala. Il est également le **Coordinateur de l&#039;équipe de recherche ISDM (Intelligent &amp; Sustainable Decision Making)**, qui fait partie du Laboratoire d&#039;Informatique Appliquée (LIA) de la même faculté.\r\n\r\n**Formation Académique :**\r\nIl est titulaire d&#039;un **Doctorat en Informatique** obtenu à l&#039;Institut National Polytechnique de Toulouse (INPT) en France. Il est également qualifié CNU de France (27ème session).\r\n\r\n**Domaines de Recherche :**\r\nSes activités de recherche sont vastes et se concentrent principalement sur :\r\n*   **Intelligence Artificielle**\r\n*   **Systèmes d&#039;Aide à la Décision**\r\n*   **Interopérabilité**\r\n*   **Ingénierie des Connaissances**\r\n*   **Systèmes de Transport**\r\n*   **Systèmes Durables**\r\n*   **Gestion des connaissances**\r\n*   **Flou (Fuzziness)**\r\n\r\n**Contributions et Focus Spécifiques :**\r\nLe Professeur Moskolaï Ngossaha s&#039;intéresse particulièrement à l&#039;amélioration de la conception et de la mise en œuvre de **systèmes de mobilité urbaine durable**, notamment dans le contexte des pays en développement. Ses travaux visent à utiliser la gestion et l&#039;analyse des données urbaines pour améliorer la qualité de vie, l&#039;environnement et les systèmes de mobilité. Il explore comment les gestionnaires urbains peuvent utiliser ces données pour améliorer la mobilité urbaine, en se concentrant sur l&#039;élicitation des connaissances et l&#039;évaluation de la durabilité d&#039;un système de mobilité urbaine par la simulation, afin de guider la prise de décision vers la mise en œuvre de &quot;Smart Cities&quot;.\r\n\r\nIl a notamment développé des méthodologies intégrant des approches de **décision multicritères floues** pour évaluer et sélectionner les services de mobilité urbaine les plus durables et écologiquement responsables. Ses recherches abordent également l&#039;optimisation des systèmes de mobilité urbaine cyber-physiques dans les pays en développement.\r\n\r\n**Publications et Collaborations :**\r\nLe Professeur Moskolaï Ngossaha est un auteur prolifique, avec de nombreuses publications dans des revues et conférences scientifiques. Il collabore avec d&#039;autres chercheurs nationaux et internationaux sur divers projets.', '8ff71e1010b15fc28d4cb6f0e328d86ac5371b7cdc9b7f0508a53ec1e25b532f', 'informations', 1, '2026-03-25 09:59:55'),
(28, 3, 'tu peux me donner quels autres informations sur la faculté des sciences?', 'La Faculté des Sciences (FS) de l&#039;Université de Douala est un pôle d&#039;excellence pour l&#039;enseignement et la recherche scientifique au Cameroun. Voici quelques informations supplémentaires :\r\n\r\n**Localisation et Infrastructures :**\r\nLa Faculté des Sciences est principalement située sur le **Campus de PK17** à Douala, où se trouvent le Décanat, les salles de cours, les laboratoires et un amphithéâtre. Elle dispose également d&#039;un amphithéâtre au campus I et bénéficie de locaux à l&#039;ancien Rectorat à Akwa, qui abritent notamment le CEPAMOQ (Centre de Physique Atomique Moléculaire et Optique Quantique). La Faculté partage aussi des salles de cours et deux amphithéâtres de 500 places avec d&#039;autres facultés au campus II à Ndogbong.\r\n\r\n**Cycles d&#039;Études :**\r\nLa Faculté des Sciences propose les trois cycles du système LMD (Licence, Master, Doctorat) :\r\n*   **Premier Cycle (Licence) :** D&#039;une durée de trois ans (six semestres), il couvre les niveaux I à III et comprend des enseignements fondamentaux, de formation bilingue et de professionnalisation.\r\n*   **Deuxième Cycle (Master) :** D&#039;une durée de deux ans (quatre semestres), il couvre les niveaux IV et V.\r\n*   **Troisième Cycle (Doctorat) :** Le CEPAMOQ, par exemple, assure une formation doctorale à partir du Master 2 en Physique de la Matière et du Rayonnement.\r\n\r\n**Départements :**\r\nLa Faculté des Sciences est structurée en plusieurs départements, parmi lesquels on retrouve :\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Sciences de la Terre\r\n*   Physique\r\n*   Mathématiques et Informatique\r\n*   Chimie\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\n**Conditions d&#039;Admission :**\r\nL&#039;inscription à la Faculté des Sciences de l&#039;Université de Douala est généralement ouverte aux titulaires des BAC C, D, E, F et TI, ainsi qu&#039;aux titulaires du GCE &quot;AL&quot; obtenu en au moins deux matières scientifiques, et du GCE &quot;OL&quot; obtenu en quatre matières dont au moins deux scientifiques (Mathématiques, Physique, Chimie, Biologie, Informatique). Des conditions supplémentaires peuvent être requises en fonction de la filière sollicitée.\r\n\r\n**Formations :**\r\nEn plus des filières classiques, la Faculté des Sciences propose également des filières professionnelles, notamment des Diplômes d&#039;Études Universitaires Professionnelles (DEUP), des Licences Professionnelles et des Masters Professionnels dans des domaines variés comme le Génie Informatique et Décisionnel, la Microbiologie Médicale, la Production, transformation et conservation des produits agricoles, les Techniques de Laboratoires, la Qualité Sécurité Environnement (QSE), les Biotechnologies, Diététique et Nutrition, et les Méthodes Informatiques Appliquées à la Gestion des Entreprises (MIAGE).\r\n\r\n**Mission et Objectifs :**\r\nLa mission de l&#039;Université de Douala, dont fait partie la Faculté des Sciences, est l&#039;élaboration et la transmission des connaissances, le développement de la recherche et la formation des hommes. Elle vise à procurer l&#039;accès à la formation supérieure à tous ceux qui en ont la vocation et la capacité, et à contribuer au développement et à la promotion sociale et culturelle. L&#039;objectif est de fournir un environnement sûr et heureux aux étudiants, où ils pourront s&#039;épanouir tout en acquérant les connaissances nécessaires pour leurs carrières professionnelles.', 'dc3fd81c081b50c4f4623ca2ccd1c6383c6a1fbbe84fad63e0bb6026991fa258', 'informations', 1, '2026-03-25 10:01:42'),
(29, 3, 'bonjour', 'Bonjour ! Comment puis-je vous aider aujourd&#039;hui ?', '2cb4b1431b84ec15d35ed83bb927e27e8967d75f4bcd9cc4b25c8d879ae23e18', 'informations', 1, '2026-03-25 10:09:56'),
(30, 3, 'parle moi de pr justin moskolai', 'On a déjà abordé le sujet du Pr. Justin Moskolaï en détail. Que souhaitez-vous savoir de plus ? Pour vous rafraîchir la mémoire, voici un résumé :\r\n\r\nLe Professeur Justin Moskolaï Ngossaha est Maître de Conférences et chercheur en Informatique à la Faculté des Sciences de l&#039;Université de Douala. Il est un expert en Intelligence Artificielle, Systèmes d&#039;Aide à la Décision, et Mobilité Urbaine Durable. Il dirige l&#039;équipe de recherche ISDM et est qualifié CNU de France.\r\n\r\nQu&#039;est-ce qui vous intéresse plus particulièrement chez le Prof. Moskolaï ? Peut-être concernant ses projets actuels, ses publications spécifiques, ou son parcours ?', 'de24e686c68e9d38336b79fec69b049f1a06b86d660d1105aa1e8dbf3dfcdda4', 'informations', 1, '2026-03-25 10:10:34'),
(31, 3, 'qui est le doyen de la facultés des sciences ?', 'La Doyenne de la Faculté des Sciences de l&#039;Université de Douala est le **Professeur Marie Joseph Ntamak**.', '953b6cacbba9b2af55a98409ce3b1ed01c9dac3e01bd6a40b0b67c2fd597e95b', 'informations', 1, '2026-03-26 10:22:08'),
(33, 3, 'quels sont les conditions d&#039;eligibilite en master ?', 'Pour être éligible à un Master à la Faculté des Sciences de l&#039;Université de Douala, les conditions générales sont les suivantes :\r\n\r\n1.  **Diplôme requis** : Il faut être titulaire d&#039;une Licence (BAC+3) ou d&#039;un diplôme équivalent dans la spécialité correspondante au Master visé. Pour les Masters professionnels, un niveau BAC+3 ou équivalent est requis.\r\n2.  **Étude de dossier** : L&#039;admission se fait généralement sur étude de dossier.\r\n3.  **Dossier de candidature** : Le dossier comprend typiquement :\r\n    *   Des photocopies de l&#039;acte de naissance (dont une légalisée).\r\n    *   Des photocopies du diplôme de Licence ou équivalent (dont une légalisée).\r\n    *   Les relevés du dernier diplôme obtenu.\r\n    *   Une lettre de motivation et un CV peuvent être demandés.\r\n    *   Des photos d&#039;identité.\r\n    *   Une fiche d&#039;inscription.\r\n    *   Un reçu de paiement des frais d&#039;étude de dossier.\r\n4.  **Frais de pré-inscription** : Des frais de pré-inscription sont à payer, par exemple 10 000 FCFA à la UBA pour la pré-inscription en ligne.\r\n5.  **Processus de pré-inscription en ligne** : La pré-inscription se fait en ligne sur des plateformes dédiées comme www.systhag-online.cm ou www.facscienceunivdouala.cm.\r\n6.  **Sélection** : Après l&#039;étude des dossiers, les listes des étudiants pré-inscrits sont affichées.\r\n\r\nIl est important de noter que les conditions spécifiques peuvent varier légèrement en fonction de la filière de Master (Master Recherche ou Master Professionnel) et du département. Il est toujours recommandé de consulter les annonces officielles de la Faculté des Sciences ou de contacter directement le département concerné pour les informations les plus précises et à jour.', '86187c9c7970ddb9ab7ce2a46d24da777baba27e2e64b8331843d99b55546cc0', 'informations', 1, '2026-03-26 10:23:56'),
(39, 3, 'qui travaille a la cellule informatique?', 'Je n&#039;ai pas trouvé d&#039;informations spécifiques sur les personnes travaillant dans une &quot;cellule informatique&quot; administrative ou de support technique pour l&#039;ensemble de la Faculté des Sciences de l&#039;Université de Douala.\r\n\r\nCependant, la Faculté des Sciences abrite le **Laboratoire d&#039;Informatique Appliquée (LIA)** et le **Département de Mathématiques et Informatique**, où travaillent des enseignants-chercheurs et des chercheurs dans le domaine de l&#039;informatique.\r\n\r\nAu sein du Laboratoire d&#039;Informatique Appliquée (LIA), on trouve notamment :\r\n*   **Dr. Joseph MVOGO NGONO** (Directeur)\r\n*   **Pr. Samuel BOWONG** (Directeur)\r\n*   **Dr Vigny NOUMSI WOGUIA** (Directeur)\r\n*   **Dr Justin MOKOLAI NGOSSAHA** (Superviseur de l&#039;équipe ISDM)\r\n*   **Dr Joseph MVONGO NGONO** (Superviseur de l&#039;équipe d&#039;imagerie et signal)\r\n\r\nL&#039;équipe de recherche ISDM (Intelligent &amp; Sustainable Decision Making) du Département de Mathématiques et Informatique comprend également :\r\n*   **Pr. Justin MOSKOLAI** (Coordonnateur de l&#039;équipe de recherche)\r\n*   **Dr Rodrigue DJEUMEN** (Responsable des Projets)\r\n*   **Dr Bertrand MBAMA** (Responsable de la Coopération)\r\n*   **Dr Yannick MALONG** (Responsable de l&#039;innovation)\r\n\r\nSi votre question concerne le personnel technique ou administratif en charge de l&#039;infrastructure informatique ou du support aux utilisateurs pour la faculté, ces informations ne sont pas disponibles dans les résultats de ma recherche.', 'acecd32da9d4837cc27868f4c2cb615f8943ebb0fbdce02923806cc7cda8a526', 'informations', 1, '2026-03-26 11:16:32'),
(40, 3, 'où se font les paiements des droits universitaires à la faculté des sciences ?', 'Les paiements des droits universitaires à la Faculté des Sciences de l&#039;Université de Douala se font principalement auprès de la **United Bank for Africa (UBA)**.\r\n\r\nUBA déploie des postes de paiement sur tous les campus pour faciliter ces transactions.\r\n\r\nLe processus général implique souvent une pré-inscription en ligne, suivie du paiement des frais (y compris les droits universitaires) à la banque, puis le téléchargement des quitus de paiement via les plateformes en ligne de l&#039;université.', '317c4db10e4c820011581672f52e9913a3f428608a884be09396666680aa20b5', 'informations', 1, '2026-03-26 11:28:36');
INSERT INTO `ai_cache` (`id`, `user_id`, `question_text`, `answer_text`, `question_hash`, `mode`, `hits`, `last_used`) VALUES
(41, 3, 'comment me preinscrire à la faculté des sciences ?', 'Pour te préinscrire à la Faculté des Sciences de l&#039;Université de Douala, voici les étapes à suivre, basées sur les informations disponibles:\r\n\r\n**1. Vérifier les conditions d&#039;admission :**\r\nAssure-toi de posséder le diplôme requis pour l&#039;admission à la Faculté des Sciences. Il s&#039;agit généralement d&#039;un Baccalauréat C, D, E, F, TI, ou un GCE AL scientifique avec au moins deux matières scientifiques, et un GCE OL avec au moins deux matières scientifiques (Mathématiques, Physique, Chimie, Biologie, Informatique). Pour les filières Mathématiques et Informatique, un Baccalauréat C ou E est souvent obligatoire, ou un Bac D avec une moyenne d&#039;au moins 12/20 en Mathématiques.\r\n\r\n**2. Effectuer la préinscription en ligne :**\r\nRends-toi sur la plateforme Systhag Online à l&#039;adresse : [http://www.systhag-online.cm:8080/SYSTHAG-ONLINE/](http://www.systhag-online.cm:8080/SYSTHAG-ONLINE/). Tu peux aussi trouver des liens sur le site de la Faculté des Sciences.\r\n\r\n**3. Payer les frais de préinscription et autres frais :**\r\nTu devras payer les frais de préinscription, les frais de visite médicale (et effectuer la visite médicale au centre médico-social de l&#039;Université de Douala), ainsi qu&#039;au moins la première tranche des droits universitaires. Ces paiements se font généralement auprès de la United Bank for Africa (UBA). Les frais de préinscription sont de 10 000 FCFA.\r\n\r\n**4. Scanner et importer les documents requis :**\r\nScanne les documents nécessaires et importe-les sur la plateforme. Les documents doivent être en format image lisible et ne pas dépasser 1 Mo. Voici la liste des documents à scanner:\r\n*   Photo portrait 4x4 lisible en couleur.\r\n*   Photocopie certifiée conforme de l&#039;acte de naissance (datant de moins de trois mois).\r\n*   Fiche de préinscription signée par l&#039;étudiant.\r\n*   Certificat médical délivré par le centre médico-social de l&#039;Université de Douala.\r\n*   Photocopie certifiée conforme du Probatoire ou GCE OL.\r\n*   Photocopie certifiée conforme du Baccalauréat ou GCE AL.\r\n*   Les reçus et quitus certifiés et validés de préinscription.\r\n*   Les reçus et quitus certifiés et validés d&#039;au moins la première tranche des droits universitaires (ou des deux tranches si tu as payé la totalité).\r\n*   Pour les candidats en Licence professionnelle, Master professionnel ou Master classique, soumets les relevés du dernier diplôme obtenu et le dernier diplôme en question à la place du Probatoire et du Baccalauréat.\r\n\r\n**5. Valider tes données :**\r\nUne fois tous les documents importés, clique sur le bouton &quot;valider&quot; pour enregistrer tes données.\r\n\r\n**6. Déposer le dossier physique :**\r\nAprès avoir soumis la version numérique, tu devras déposer une version physique de ton dossier au Campus 3 situé à PK17, selon un programme qui sera communiqué. Pour les candidats retenus, le dossier physique est à déposer auprès des secrétariats des départements situés au Campus 1 à Ange Raphaël, Bâtiment C.\r\n\r\nIl est important de noter que les dates de préinscription sont annoncées par un communiqué du Recteur de l&#039;Université, généralement à partir du mois de septembre de chaque année. Les pré-inscriptions pour l&#039;année académique 2025-2026 sont ouvertes tous les jours.\r\n\r\nPour toute erreur constatée (filière, niveau, nom, etc.), signale-le à la scolarité après le paiement des droits universitaires.', '35872ae5d2b5adb2b23b67c2d51c6acea78479f865c42221d7317d001c14bb0f', 'informations', 1, '2026-03-28 11:05:48'),
(42, 3, 'quels sont les unités d’enseignement pour les licence 1 en informatique ?', 'Pour la Licence 1 en Informatique à la Faculté des Sciences de l&#039;Université de Douala, les Unités d&#039;Enseignement (UE) sont réparties sur deux semestres et couvrent des domaines fondamentaux de l&#039;informatique et des mathématiques, ainsi que des compétences complémentaires.\r\n\r\nVoici une liste des principales Unités d&#039;Enseignement pour la Licence 1 en Informatique:\r\n\r\n**UE Fondamentales :**\r\n*   **INF 111 :** Introduction à l&#039;algorithme (6 crédits)\r\n*   **INF 121 :** Architecture des ordinateurs (6 crédits)\r\n*   **INF 131 :** Programmation structurée (C ou Python) (6 crédits)\r\n*   **MAT 121 :** Analyse 1 : analyse de la droite vectorielle réelle (6 crédits)\r\n*   **INF 112 :** Introduction à la programmation fonctionnelle (6 crédits)\r\n*   **INF 122 :** Introduction aux réseaux (6 crédits)\r\n*   **INF 132 :** Introduction aux systèmes d&#039;exploitation (6 crédits)\r\n*   **MAT 112 :** Algèbre linéaire (6 crédits)\r\n\r\n**UE Complémentaires :**\r\n*   **INF 141 :** Éducation civique et éthique (3 crédits)\r\n*   **INF 142 :** Formation bilingue 1 (3 crédits)\r\n\r\n**UE Optionnelles au choix (exemples) :**\r\n*   **INF 151 :** Électrostatique (3 crédits)\r\n*   **INF 161 :** Introduction au droit (3 crédits)\r\n*   **INF 171 :** Programmation web statique (3 crédits)\r\n*   **INF 152 :** Électronique numérique (3 crédits)\r\n*   **INF 162 :** Programmation C++ (3 crédits)\r\n*   **INF 172 :** Mécanique du point (3 crédits)\r\n\r\nCe programme vise à fournir aux étudiants une base solide en informatique et en mathématiques, essentielle pour la poursuite de leurs études dans le domaine.', '8da57a9a63a5d4313e98190170effe76ee29d9237db73b7b078b51659f56f6d9', 'informations', 1, '2026-03-28 11:06:55'),
(43, 3, 'parle moi des laboratoires de recherche de là facultés des sciences', 'La Faculté des Sciences de l&#039;Université de Douala abrite plusieurs laboratoires de recherche qui mènent des travaux fondamentaux et appliqués dans divers domaines scientifiques. Voici quelques-uns de ces laboratoires :\r\n\r\n*   **Laboratoire des Géosciences, ressources naturelles et environnement** : Ce laboratoire se concentre sur la recherche fondamentale et appliquée concernant les matériaux de l&#039;écorce terrestre et les combustibles fossiles, en intégrant une dimension environnementale. Il est structuré autour de deux grands axes de recherche avec cinq équipes.\r\n\r\n*   **Laboratoire d&#039;Informatique Appliquée (LIA)** : Le LIA est un centre de recherche multidisciplinaire dédié à l&#039;étude et au développement de solutions innovantes en informatique. Ses activités couvrent des domaines clés pour répondre aux défis technologiques et sociétaux actuels, avec un engagement à produire des recherches de pointe et à former des experts. Il est organisé autour de deux équipes de recherche :\r\n    *   L&#039;équipe **ISDM (Intelligent &amp; Sustainable Decision Making)**, supervisée par le Dr Justin MOKOLAI NGOSSAHA.\r\n    *   L&#039;équipe d&#039;**Imagerie et Signal**, supervisée par le Dr Joseph MVONGO NGONO.\r\n    Le LIA coordonne également les formations de master et les thèses.\r\n\r\n*   **Laboratoire de Biologie et Physiologie Animale** : Ce laboratoire mène des recherches sur la valorisation des sols et des matériaux, la dépollution des villes, et le traçage géochimique. Il est impliqué dans des projets tels que la résorption de la pollution urbaine et la caractérisation des ressources du sous-sol.\r\n\r\n*   **Laboratoire de Chimie** : Bien que les détails spécifiques de ses axes de recherche ne soient pas entièrement précisés dans les résultats, il est mentionné comme un laboratoire de la Faculté des Sciences de l&#039;Université de Douala.\r\n\r\nEn outre, d&#039;autres laboratoires sont associés à l&#039;Université de Douala et contribuent à la recherche scientifique, bien que leur rattachement direct à la Faculté des Sciences ne soit pas toujours explicitement détaillé dans toutes les sources :\r\n\r\n*   **Laboratoire de Technologies et Sciences Appliquées (LTSA)** : Créé en 2017, le LTSA est un laboratoire de recherche appartenant à l&#039;Unité de Formation Doctorale des Sciences Appliquées (UFD-SCA) de l&#039;École Doctorale des Sciences Fondamentales et Appliquées (EDOSFA) de l&#039;Université de Douala. Il est hébergé à l&#039;Institut Universitaire de Technologies (IUT) de Douala.\r\n\r\n*   **IBHI Lab** : Ce laboratoire est également associé à l&#039;Université de Douala et mène des activités de recherche, comme en témoignent ses actualités et publications.', '8291424144cf12aecbcc73bad1105cf1cda7480ad4f8f5ad7b20e1ac0a37d881', 'informations', 1, '2026-03-28 11:07:37'),
(44, 3, 'parle mon du laboratoire isdm', 'Le laboratoire ISDM, acronyme de &quot;Intelligent &amp; Sustainable Decision Making&quot;, est une équipe de recherche interdisciplinaire rattachée au Département de Mathématiques et Informatique de la Faculté des Sciences de l&#039;Université de Douala. Il fait partie du Laboratoire d&#039;Informatique Appliquée (LIA).\r\n\r\nL&#039;équipe ISDM est composée d&#039;enseignants-chercheurs et de jeunes chercheurs passionnés, animés par une forte culture scientifique et un engagement sociétal.\r\n\r\n**Axes de recherche :**\r\nLes activités scientifiques de l&#039;équipe ISDM s&#039;articulent autour de cinq axes de recherche interconnectés, à l&#039;interface de l&#039;intelligence artificielle, de la science des données et de la durabilité des systèmes complexes :\r\n*   **Intelligence Artificielle Urbaine :** Développement de modèles et d&#039;outils d&#039;IA pour la planification, la gestion et l&#039;évolution intelligente des villes africaines, en intégrant les dimensions sociales, économiques et environnementales.\r\n*   **Ingénierie des Connaissances et Systèmes d&#039;Interopérabilité :** Conception de méthodes et de technologies pour la capture, la modélisation, le partage et l&#039;exploitation des connaissances, favorisant l&#039;interopérabilité entre systèmes hétérogènes et le pilotage coordonné de services urbains et territoriaux.\r\n*   **Systèmes de Communication Durables et IoT (Internet des Objets) :** Recherche sur les systèmes de communication durables et l&#039;Internet des Objets.\r\n*   **Conception de Systèmes Complexes et Aide à la Décision :** Modélisation et structuration de systèmes intelligents capables de fonctionner efficacement dans des environnements dynamiques, contraints et incertains. Cet axe intègre des outils issus de la théorie des jeux et de l&#039;aide à la décision multicritère (ADM) pour traiter des décisions complexes.\r\n*   **Jumeaux Numériques et Process Mining :** Exploration des jumeaux numériques et du &quot;process mining&quot;.\r\n\r\n**Vision et impact :**\r\nLes recherches de l&#039;équipe ISDM visent à concevoir des solutions intelligentes, robustes et durables pour répondre aux grands défis du développement en Afrique. Cela inclut la transformation numérique des villes et des territoires, l&#039;amélioration de la gouvernance et de la prise de décision, l&#039;optimisation des ressources et des infrastructures, ainsi que la promotion d&#039;un développement inclusif et résilient.\r\n\r\n**Membres clés :**\r\n*   **Pr. Justin MOSKOLAI :** Coordonnateur de l&#039;équipe de recherche.\r\n*   **Dr Rodrigue DJEUMEN :** Responsable des Projets.\r\n*   **Dr Bertrand MBAMA :** Responsable de la Coopération.\r\n*   **Dr Yannick MALONG :** Responsable de l&#039;innovation.\r\n*   **Pr. Samuel BOWONG :** Responsable du Département Maths-Info.\r\n\r\nL&#039;équipe ISDM est également impliquée dans la coordination des formations de master et des thèses au sein du Laboratoire d&#039;Informatique Appliquée (LIA).', '887e07925e7f2a2ac288906189e66e04f8426c4d06acf6fc0ac2a9030760ee6f', 'informations', 1, '2026-03-28 11:08:08'),
(45, 3, 'qui est mr ndje jonathan', 'Mr. NDJE JONATHAN, dont le nom complet est Yves Jonathan NDJE, est un Enseignant Assistant au Département de Mathématiques-Informatique de l&#039;Université de Douala depuis septembre 2008. Il est également membre de l&#039;équipe ISDM, une équipe de recherche du même département au sein de la Faculté des Sciences de l&#039;Université de Douala.', '82a51a07d6c7b1596edcbc237ed55523e358c47b3345680fe2f56af869119186', 'enseignants', 1, '2026-04-01 17:44:00'),
(46, 3, 'parle moi de l&#039;équipe isdm', 'L&#039;équipe ISDM, dont le nom complet est &quot;Intelligent &amp; Sustainable Decision Making&quot;, est une équipe de recherche interdisciplinaire rattachée au Département de Mathématiques et Informatique de la Faculté des Sciences de l&#039;Université de Douala.\r\n\r\nElle est composée d&#039;enseignants-chercheurs et de jeunes chercheurs, animés par une forte culture scientifique et un engagement sociétal affirmé.\r\n\r\nL&#039;équipe ISDM développe des travaux de recherche à l&#039;interface de l&#039;intelligence artificielle, de la science des données et de la durabilité des systèmes complexes.\r\n\r\nSes axes de recherche incluent :\r\n*   L&#039;Intelligence Artificielle Urbaine.\r\n*   L&#039;Ingénierie des Connaissances et Systèmes d&#039;Interopérabilité.\r\n*   Les Systèmes de Communication Durables et l&#039;IoT (Internet des Objets).\r\n*   La Conception de Systèmes Complexes et l&#039;Aide à la Décision.\r\n*   Les Jumeaux Numériques et le Process Mining.\r\n\r\nLe Professeur Justin MOSKOLAI est le coordonnateur de l&#039;équipe de recherche.', '872c58bfbe0521571c39bcfb2a7d7b0affd42079c1dbdef1a6095e9a2e4888b2', 'informations', 1, '2026-04-01 17:45:26'),
(47, 3, 'qui est dongmo?', 'Le nom &quot;Dongmo&quot; est porté par plusieurs personnalités au Cameroun, notamment au sein de l&#039;Université de Douala. Voici quelques-unes d&#039;entre elles :\r\n\r\n*   **Dongho Dongmo Fabrice Fabien** est Professeur Associé au Département de Biochimie de l&#039;Université de Douala. Ses domaines d&#039;expertise incluent les produits naturels, les antioxydants, les acides gras, et les maladies métaboliques.\r\n*   **Jean de dieu Dongmo** est Docteur en Philosophie au Département de Chimie de l&#039;Université de Douala.\r\n*   **Alain Dongmo** est associé au Département de Biologie des Organismes Animaux de l&#039;Université de Douala.\r\n*   **Roméo Martial DONGMO** est de la Faculté des Sciences Économiques et de Gestion Appliquée de l&#039;Université de Douala et a publié sur le reporting de durabilité.\r\n\r\nIl existe également d&#039;autres personnalités notables portant ce nom au Cameroun, bien que n&#039;étant pas directement rattachées à la Faculté des Sciences de l&#039;Université de Douala dans les informations disponibles :\r\n\r\n*   Le **Professeur Bernard-Raymond Guimdo Dongmo**, expert en droit public et science politique, né à Douala, a enseigné dans', 'ba861ed637433f6dd41ea9386668ebcad60d3fcecb25d948eedfd573c6178304', 'informations', 1, '2026-04-01 17:47:52'),
(48, 3, 'ou est situe le bureau de pr moskolai?', 'Le Professeur Justin MOSKOLAI est Enseignant Chercheur au Département de Mathématiques et Informatique de la Faculté des Sciences de l&#039;Université de Douala. Bien que son appartenance à ce département soit claire, les informations disponibles ne précisent pas le numéro exact de son bureau ou le bâtiment spécifique où il est situé.', 'e1d1d078e2d88f8fc4fcac18024976deed57fe6d064447552fc258a1967eb8f7', 'informations', 1, '2026-04-01 17:49:11'),
(52, 3, 'qui est mr ndje ?', 'Monsieur Ndje, de son nom complet Yves Jonathan Ndje, est le maréchal de la Faculté des Sciences.', 'a9c64d4946c62d6b6f9c5212f8dfca0d58d2b0df7b7dbc4218590bd22076e58b', 'informations', 1, '2026-04-02 20:51:24'),
(57, 3, 'qui est pr moskolai?', 'Dans un contexte de la Faculté des Sciences, vu les informations additionnelles que vous m\'avez fournies précédemment, il est probable, et même très probable, que le Pr. Moskolai soit le Professeur Justin Moskolai, qui est le coordonnateur de l\'équipe de recherche ISDM (Intelligent & Sustainable Decision Making) au sein du Laboratoire d\'Informatique Appliquée (LIA). Cependant, ces renseignements ne figurent pas dans les nouvelles informations que vous m\'avez communiquées. Je ne peux donc le confirmer avec certitude seulement avec ces données.\r\n', 'b0ff3fa3d0bcaf3b637a1828bcaf24e124100360ee6440aceb286636112c5465', 'informations', 1, '2026-04-07 21:21:09'),
(61, 3, 'qui est dr fotsing?', 'Le Dr. FOTSING TETSING Jean est un enseignant au Département de Mathématiques et Informatique.\r\n', '270bdfd97b1255cf98cbb012fe48b479d7b2e9394991773f5b595050dc92436b', 'enseignants', 1, '2026-04-07 21:31:34'),
(62, 3, 'quand aura lieu la rentree en 2026 ?', 'La rentrée académique 2026-2027 est programmée pour le mardi 1er septembre 2026.', '40f5424ad45ea1c45c6d04c6feb0d9147067716d1912882220aeaa25a9879a85', 'informations', 1, '2026-07-20 09:58:49'),
(63, 3, 'comment s&#039;inscrire en filiere lida à la faculte?', 'Pour vous inscrire en filière LIDA à la faculté, vous devez effectuer une préinscription en ligne sur les sites officiels SYSTHAG Online ou FS-Univ-Dla. Cette préinscription se fait sur étude de dossier. Les inscriptions en ligne sont généralement ouvertes du 25 août au 30 septembre pour les nouveaux étudiants. La filière LIDA est une Licence Professionnelle (Informatique Décisionnelle) proposée par la faculté.', '8580771bb78638bd8c7646c3a856d6833087ebd54253c4645a1c7db86d9405b1', 'informations', 1, '2026-07-20 09:59:30'),
(64, 3, 'ou se trouve le bureau de la cellule informatique?', 'La Faculté des Sciences de l\'Université de Douala est située au Campus PK17. Il est probable que le bureau de la cellule informatique se trouve également sur ce campus, qui abrite le Décanat, les salles de cours et les laboratoires.\r\n\r\nPour obtenir l\'emplacement exact du bureau de la cellule informatique, je vous recommande de contacter directement la Faculté des Sciences via les numéros de téléphone suivants : +237 697 449 991 ou +237 681 564 947, ou par email à infos@fs-univ-douala.cm.', '28f1b7139dbf3684fa847c997e8ce49f2ec16b91243aa43eb05ce752509c67c6', 'informations', 1, '2026-07-20 10:00:20'),
(65, 3, 'ou as tu pris l&#039;information sur la date de la rentree de la faculte des sciences?', 'Je n\'ai pas trouvé d\'information sur la date de la rentrée de la Faculté des Sciences dans les documents que j\'ai consultés. Les informations disponibles concernent les procédures de préinscription, les évaluations et les actualités récentes, mais pas le calendrier de la rentrée universitaire.', '0d23c27a22fd3ad150facf8127ea035b6d2f295827f58eeb382ae32224e0d956', 'informations', 1, '2026-07-20 10:53:24'),
(66, 3, 'qui est le chef de la faculte des sciences?', 'Le chef de la Faculté des Sciences est le Doyen, et le Doyen actuel est le Professeur Marie Joseph Ntamak Nida.', 'cfe1e0d5f0d3db608d21ed7a74cdbd2b97581988c6dd18134d62e9738297d8f2', 'informations', 1, '2026-07-20 10:54:28');
INSERT INTO `conversations` (`id`, `user_id`, `session_id`, `message_user`, `reponse_ai`, `mode`, `date_created`) VALUES
(29, 3, '12455768', 'parle moi de la faculte des sciences', 'La Faculté des Sciences (FS) de l\'Université de Douala est située sur le campus de PK17, qui abrite le Décanat, les salles de cours, les laboratoires et un amphithéâtre. Elle a été créée en 1993.\r\n\r\nElle propose des formations dans trois cycles d\'études : Licence (3 ans), Master (2 ans) et Doctorat.\r\n\r\nLa Faculté des Sciences est structurée en plusieurs départements, parmi lesquels on trouve:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n\r\nElle offre également des filières professionnelles en plus des formations initiales classiques. Les conditions d\'admission requièrent généralement un Baccalauréat scientifique (C, D, E, F, TI) ou un GCE \"AL\" avec au moins deux matières scientifiques.', 'informations', '2026-03-23 15:56:24'),
(30, 3, '12455768', 'comment faire les preinscriptions a la faculte des sciences?', 'Pour faire les pré-inscriptions à la Faculté des Sciences de l\'Université de Douala, voici les étapes à suivre :\r\n\r\n1.  **Conditions d\'admission** : Vous devez être titulaire d\'un Baccalauréat scientifique (C, D, E, F, T) ou d\'un GCE-AL obtenu avec au moins deux matières scientifiques.\r\n2.  **Pré-inscription en ligne** : La pré-inscription se fait uniquement sur étude de dossier via les plateformes en ligne.\r\n    *   Connectez-vous sur le site www.systhag-online.cm ou www.facscienceunivdouala.cm.\r\n    *   Un communiqué du Recteur de l\'Université annonce le début et la fin des pré-inscriptions sur www.systhag-online.cm.\r\n3.  **Paiement des frais de pré-inscription** :\r\n    *   Les frais de pré-inscription s\'élèvent à 10 000 (dix mille) francs CFA.\r\n    *   Le paiement se fait à UBA (United Bank for Africa), qui peut déployer des postes de paiement sur les campus.\r\n    *   Vous devrez également payer les frais de visite médicale et au moins la première tranche des droits universitaires.\r\n4.  **Dépôt des pièces du dossier en ligne** :\r\n    *   Connectez-vous à www.facsciences-online.cm pour déposer les pièces de votre dossier en ligne.\r\n    *   Les documents à scanner et importer (en format image lisible et ne dépassant pas 1 Mo) incluent : une photo portrait 4x4, une photocopie certifiée conforme de l\'acte de naissance, la fiche de pré-inscription signée, le certificat médical délivré par le centre médico-social de l\'Université de Douala, les photocopies certifiées conformes du probatoire (ou GCE OL) et du Baccalauréat (ou GCE AL), ainsi que les reçus et quitus de paiement des frais de pré-inscription et des droits universitaires.\r\n5.  **Téléchargement et impression** : Téléchargez et imprimez la fiche de pré-inscription et le quitus de paiement des frais de pré-inscription à l\'adresse www.systhag-online.cm.\r\n6.  **Validation de la candidature** : Après avoir importé tous les documents, cliquez sur \"valider\" pour enregistrer vos données.\r\n7.  **Affichage des listes** : Après l\'affichage des listes d\'étudiants pré-inscrits, vous devrez relever votre numéro de pré-inscription.\r\n8.  **Paiement des droits universitaires** : Téléchargez les quitus de paiement des deux tranches (DU) grâce à votre numéro de pré-inscription, puis payez la 1ère ou les deux tranches pour obtenir un numéro matricule unique.\r\n\r\nLes renseignements afférents sont disponibles à la scolarité de la Faculté dès le mois de Septembre de chaque année. Les pré-inscriptions pour l\'année académique 2025-2026 sont ouvertes tous les jours.', 'informations', '2026-03-23 15:57:24'),
(31, 3, '12455768', 'bonsoir', 'Bonsoir ! Comment puis-je vous aider ce soir ?', 'informations', '2026-03-23 16:03:59'),
(32, 3, '12455768', 'bonsoir', 'Bonsoir ! Comment puis-je vous aider ce soir ?', 'informations', '2026-03-23 16:05:10'),
(33, 3, '12455768', 'Quels sont les enseignants de la Faculté des    Sciences?', 'Il n\'existe pas de liste publique exhaustive et constamment mise à jour de tous les enseignants de la Faculté des Sciences de l\'Université de Douala. Cependant, je peux vous donner des informations sur la structure de la faculté et des exemples de professeurs connus.\r\n\r\nLa Faculté des Sciences de l\'Université de Douala est organisée en plusieurs départements:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Le Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains professeurs de l\'Université de Douala sont mentionnés dans des documents publics, notamment dans des arrêtés de nomination ou des listes générales d\'enseignants-chercheurs. Par exemple, on peut citer :\r\n*   Monsieur YOMB Jacques, Maître de Conférences et Chef de Département.\r\n*   Monsieur MAPOURE NJANKOUO Yacouba, Professeur et Vice-Doyen chargé de la Programmation et du Suivi des Activités Académiques.\r\n*   Monsieur DOUMBE Jacques, Maître de Conférences et Chef de Département.\r\n*   Madame NGOUADJIEU Evelyne, Maître de Conférences.\r\n*   Annette Angoua Nguéa, Professeur.\r\n*   Assako Assako René Joly.\r\n*   Thomas Atenga.\r\n*   Samuel Bowong Tsakou.\r\n\r\nPour obtenir une liste plus précise et actuelle des enseignants par département, il serait préférable de consulter directement le site web officiel de la Faculté des Sciences de l\'Université de Douala (qui peut être fs-univdouala.ludovicathone.com ou fasciencedouala.com selon les sources) ou de contacter la scolarité de la Faculté.', 'informations', '2026-03-23 16:06:02'),
(34, 3, 'sess_1774282050106_tz5gey9ck', 'Quels sont les enseignants de la Faculté des Sciences?', 'En tant que fsAI, je peux vous informer que la Faculté des Sciences de l\'Université de Douala est structurée en plusieurs départements. Bien qu\'une liste exhaustive et à jour de tous les enseignants ne soit pas directement disponible via les recherches effectuées, voici les départements de la Faculté des Sciences:\r\n\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains noms d\'enseignants associés à l\'Université de Douala ont été mentionnés dans les résultats de recherche, tels que :\r\n\r\n*   Assako Assako René Joly\r\n*   Thomas Atenga\r\n*   Samuel Bowong Tsakou\r\n*   Annette Angoua Nguéa\r\n*   Monsieur YOMB Jacques (Maître de Conférences)\r\n*   Monsieur MAPOURE NJANKOUO Yacouba (Professeur)\r\n*   Madame ETOA, née ABOMO Marie Chantal (Professeur)\r\n*   Prisca Koncy Fosso (Maître Assistant)\r\n*   ELOUMOU BAGNAKA, Servais Albert Fiacre (Maître Assistant)\r\n*   Njoupouognigni, Moussa (Maître Assistant)\r\n*   ANABA EBANDA, Valéry Armel (Maître Assistant)\r\n*   DJIMEGNE EPOUSE KAMDEM, FELICITE (Maître Assistant)\r\n*   EBENDE KOUEDI, SANDRINE SARA (Maître Assistant)\r\n\r\nPour une liste complète et actualisée, il est recommandé de consulter directement le site web officiel de la Faculté des Sciences de l\'Université de Douala ou de contacter l\'administration de la faculté.', 'informations', '2026-03-23 16:07:39'),
(35, 3, 'sess_1774282050106_tz5gey9ck', 'Quels sont les enseignants de la Faculté des Sciences?', 'En tant que fsAI, je peux vous informer que la Faculté des Sciences de l\'Université de Douala est structurée en plusieurs départements. Bien qu\'une liste exhaustive et à jour de tous les enseignants ne soit pas directement disponible via les recherches effectuées, voici les départements de la Faculté des Sciences:\r\n\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains noms d\'enseignants associés à l\'Université de Douala ont été mentionnés dans les résultats de recherche, tels que :\r\n\r\n*   Assako Assako René Joly\r\n*   Thomas Atenga\r\n*   Samuel Bowong Tsakou\r\n*   Annette Angoua Nguéa\r\n*   Monsieur YOMB Jacques (Maître de Conférences)\r\n*   Monsieur MAPOURE NJANKOUO Yacouba (Professeur)\r\n*   Madame ETOA, née ABOMO Marie Chantal (Professeur)\r\n*   Prisca Koncy Fosso (Maître Assistant)\r\n*   ELOUMOU BAGNAKA, Servais Albert Fiacre (Maître Assistant)\r\n*   Njoupouognigni, Moussa (Maître Assistant)\r\n*   ANABA EBANDA, Valéry Armel (Maître Assistant)\r\n*   DJIMEGNE EPOUSE KAMDEM, FELICITE (Maître Assistant)\r\n*   EBENDE KOUEDI, SANDRINE SARA (Maître Assistant)\r\n\r\nPour une liste complète et actualisée, il est recommandé de consulter directement le site web officiel de la Faculté des Sciences de l\'Université de Douala ou de contacter l\'administration de la faculté.', 'informations', '2026-03-23 16:07:48'),
(36, 3, 'sess_1774282075358_vfxhou4i9', 'Quels sont les enseignants de la Faculté des Sciences?', 'En tant que fsAI, je peux vous informer que la Faculté des Sciences de l\'Université de Douala est structurée en plusieurs départements. Bien qu\'une liste exhaustive et à jour de tous les enseignants ne soit pas directement disponible via les recherches effectuées, voici les départements de la Faculté des Sciences:\r\n\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains noms d\'enseignants associés à l\'Université de Douala ont été mentionnés dans les résultats de recherche, tels que :\r\n\r\n*   Assako Assako René Joly\r\n*   Thomas Atenga\r\n*   Samuel Bowong Tsakou\r\n*   Annette Angoua Nguéa\r\n*   Monsieur YOMB Jacques (Maître de Conférences)\r\n*   Monsieur MAPOURE NJANKOUO Yacouba (Professeur)\r\n*   Madame ETOA, née ABOMO Marie Chantal (Professeur)\r\n*   Prisca Koncy Fosso (Maître Assistant)\r\n*   ELOUMOU BAGNAKA, Servais Albert Fiacre (Maître Assistant)\r\n*   Njoupouognigni, Moussa (Maître Assistant)\r\n*   ANABA EBANDA, Valéry Armel (Maître Assistant)\r\n*   DJIMEGNE EPOUSE KAMDEM, FELICITE (Maître Assistant)\r\n*   EBENDE KOUEDI, SANDRINE SARA (Maître Assistant)\r\n\r\nPour une liste complète et actualisée, il est recommandé de consulter directement le site web officiel de la Faculté des Sciences de l\'Université de Douala ou de contacter l\'administration de la faculté.', 'informations', '2026-03-23 16:07:58'),
(37, 3, 'sess_1774282050106_tz5gey9ck', 'quels sont les départements de la Faculté des Sciences?', 'Les départements de la Faculté des Sciences de l\'Université de Douala sont les suivants :\r\n\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)', 'informations', '2026-03-23 16:08:39'),
(38, 3, 'sess_1774282050106_tz5gey9ck', 'comment un étudiant peut faire pour aller faire un stage a l&#039;étranger quittant de la Faculté des sciences en filiere informatique niveau master 2.', 'Pour qu\'un étudiant en Master 2 Informatique de la Faculté des Sciences de l\'Université de Douala puisse effectuer un stage à l\'étranger, voici les étapes et considérations clés :\r\n\r\n1.  **Définir le projet de stage** :\r\n    *   **Objectifs** : Préciser le type d\'expérience recherchée, les compétences à développer et le secteur d\'activité souhaité.\r\n    *   **Pays et durée** : Identifier les pays cibles et la durée du stage (souvent entre 2 et 12 mois pour les programmes internationaux).\r\n\r\n2.  **Contacter les services compétents de l\'Université** :\r\n    *   **Service des Relations Internationales** : Se rapprocher du service des relations internationales de l\'Université de Douala ou de la Faculté des Sciences. Ils pourront fournir des informations sur les partenariats existants, les programmes d\'échange et les procédures internes.\r\n    *   **Responsable de la filière** : Discuter du projet avec le responsable de la filière Informatique pour s\'assurer que le stage s\'inscrit bien dans le cursus et obtenir l\'accord pédagogique.\r\n\r\n3.  **Rechercher des opportunités de stage** :\r\n    *   **Programmes spécifiques** :\r\n        *   **IAESTE Cameroun** : Cette organisation facilite les stages techniques et scientifiques rémunérés à l\'international pour les étudiants camerounais. Les candidatures sont généralement ouvertes en février pour des offres reçues en janvier, mais des opportunités sont disponibles toute l\'année.\r\n        *   **Erasmus+** : Ce programme européen offre des bourses pour des stages en Europe. L\'étudiant doit être inscrit dans un établissement ayant une charte Erasmus+ et le stage doit être en rapport avec le diplôme préparé.\r\n    *   **Plateformes de recherche** : Consulter des sites spécialisés dans les offres de stages à l\'étranger ou les réseaux professionnels.\r\n    *   **Réseau personnel et académique** : Utiliser les contacts des professeurs, anciens élèves ou professionnels du domaine.\r\n\r\n4.  **Préparer le dossier de candidature** :\r\n    *   **Documents académiques** : Relevés de notes, CV, lettre de motivation, lettres de recommandation.\r\n    *   **Compétences linguistiques** : Souvent, un bon niveau dans la langue du pays d\'accueil (attesté par des tests comme le TOEFL, IELTS, DELF/DALF) est requis.\r\n    *   **Frais** : Certains programmes comme IAESTE Cameroun peuvent impliquer des frais d\'inscription et de participation.\r\n\r\n5.  **Aspects administratifs et financiers** :\r\n    *   **Convention de stage** : Une convention de stage est obligatoire et doit être établie entre l\'étudiant, l\'Université de Douala et l\'organisme d\'accueil à l\'étranger.\r\n    *   **Financement** : Les stages à l\'étranger sont souvent rémunérés, et des bourses peuvent être disponibles via les programmes (IAESTE, Erasmus+) ou les financeurs locaux et européens. Il est important de s\'assurer que la rémun', 'informations', '2026-03-23 16:09:53'),
(39, 3, 'sess_1774282075358_vfxhou4i9', 'fait moi un racap des questions posees', 'Voici un récapitulatif des questions que vous avez posées :\r\n\r\n1.  \"Quels sont les enseignants de la Faculté des Sciences?\"\r\n2.  \"fait moi un racap des questions posees\" (la question actuelle)', 'informations', '2026-03-23 16:11:04'),
(40, 3, 'sess_1774356639252_mu6fhw1a1', 'ok', 'D\'accord. Comment puis-je vous aider aujourd\'hui ?', 'informations', '2026-03-24 12:50:49'),
(41, 3, 'sess_1774356639252_mu6fhw1a1', 'quels sont les partenaires internationaux de la facultés des sciences de l&#039;université de douala?', 'La Faculté des Sciences de l\'Université de Douala participe à des collaborations internationales, notamment :\r\n\r\n*   **Projet EDU-ABCM :** La Faculté des Sciences est membre du projet EDU-ABCM, qui implique une collaboration avec des universités de quatre pays africains (Cameroun, Éthiopie, Maurice et Mozambique) et deux universités de l\'Union Européenne (Italie et Suède). Ce projet vise à moderniser les cours et programmes dans le secteur de l\'énergie.\r\n*   **Université Paris-Saclay (France) :** L\'Université de Douala a formalisé un partenariat avec l\'Université Paris-Saclay en 2019. Cette coopération universitaire globale inclut un accord spécifique avec l\'Université Paris-Sud (membre fondateur de l\'UPSaclay), qui se traduit par des programmes d\'échange avec diverses composantes des deux universités. Bien que la Faculté des Sciences ne soit pas explicitement nommée comme partenaire direct dans ces échanges spécifiques, elle fait partie de l\'Université de Douala qui bénéficie de ce partenariat global.', 'informations', '2026-03-24 12:51:39'),
(42, 3, 'sess_1774356639252_mu6fhw1a1', 'Qui est le recteur de la faculte des sciences', 'Pour faire les pré-inscriptions à la Faculté des Sciences de l\'Université de Douala, voici les étapes à suivre :\r\n\r\n1.  **Conditions d\'admission** : Vous devez être titulaire d\'un Baccalauréat scientifique (C, D, E, F, T) ou d\'un GCE-AL obtenu avec au moins deux matières scientifiques.\r\n2.  **Pré-inscription en ligne** : La pré-inscription se fait uniquement sur étude de dossier via les plateformes en ligne.\r\n    *   Connectez-vous sur le site www.systhag-online.cm ou www.facscienceunivdouala.cm.\r\n    *   Un communiqué du Recteur de l\'Université annonce le début et la fin des pré-inscriptions sur www.systhag-online.cm.\r\n3.  **Paiement des frais de pré-inscription** :\r\n    *   Les frais de pré-inscription s\'élèvent à 10 000 (dix mille) francs CFA.\r\n    *   Le paiement se fait à UBA (United Bank for Africa), qui peut déployer des postes de paiement sur les campus.\r\n    *   Vous devrez également payer les frais de visite médicale et au moins la première tranche des droits universitaires.\r\n4.  **Dépôt des pièces du dossier en ligne** :\r\n    *   Connectez-vous à www.facsciences-online.cm pour déposer les pièces de votre dossier en ligne.\r\n    *   Les documents à scanner et importer (en format image lisible et ne dépassant pas 1 Mo) incluent : une photo portrait 4x4, une photocopie certifiée conforme de l\'acte de naissance, la fiche de pré-inscription signée, le certificat médical délivré par le centre médico-social de l\'Université de Douala, les photocopies certifiées conformes du probatoire (ou GCE OL) et du Baccalauréat (ou GCE AL), ainsi que les reçus et quitus de paiement des frais de pré-inscription et des droits universitaires.\r\n5.  **Téléchargement et impression** : Téléchargez et imprimez la fiche de pré-inscription et le quitus de paiement des frais de pré-inscription à l\'adresse www.systhag-online.cm.\r\n6.  **Validation de la candidature** : Après avoir importé tous les documents, cliquez sur \"valider\" pour enregistrer vos données.\r\n7.  **Affichage des listes** : Après l\'affichage des listes d\'étudiants pré-inscrits, vous devrez relever votre numéro de pré-inscription.\r\n8.  **Paiement des droits universitaires** : Téléchargez les quitus de paiement des deux tranches (DU) grâce à votre numéro de pré-inscription, puis payez la 1ère ou les deux tranches pour obtenir un numéro matricule unique.\r\n\r\nLes renseignements afférents sont disponibles à la scolarité de la Faculté dès le mois de Septembre de chaque année. Les pré-inscriptions pour l\'année académique 2025-2026 sont ouvertes tous les jours.', 'informations', '2026-03-25 09:43:16'),
(43, 3, 'sess_1774356639252_mu6fhw1a1', 'quels sont les departements de la Facultes des sciences?', 'Il n\'existe pas de liste publique exhaustive et constamment mise à jour de tous les enseignants de la Faculté des Sciences de l\'Université de Douala. Cependant, je peux vous donner des informations sur la structure de la faculté et des exemples de professeurs connus.\r\n\r\nLa Faculté des Sciences de l\'Université de Douala est organisée en plusieurs départements:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Mathématiques-Informatique\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Le Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nCertains professeurs de l\'Université de Douala sont mentionnés dans des documents publics, notamment dans des arrêtés de nomination ou des listes générales d\'enseignants-chercheurs. Par exemple, on peut citer :\r\n*   Monsieur YOMB Jacques, Maître de Conférences et Chef de Département.\r\n*   Monsieur MAPOURE NJANKOUO Yacouba, Professeur et Vice-Doyen chargé de la Programmation et du Suivi des Activités Académiques.\r\n*   Monsieur DOUMBE Jacques, Maître de Conférences et Chef de Département.\r\n*   Madame NGOUADJIEU Evelyne, Maître de Conférences.\r\n*   Annette Angoua Nguéa, Professeur.\r\n*   Assako Assako René Joly.\r\n*   Thomas Atenga.\r\n*   Samuel Bowong Tsakou.\r\n\r\nPour obtenir une liste plus précise et actuelle des enseignants par département, il serait préférable de consulter directement le site web officiel de la Faculté des Sciences de l\'Université de Douala (qui peut être fs-univdouala.ludovicathone.com ou fasciencedouala.com selon les sources) ou de contacter la scolarité de la Faculté.', 'informations', '2026-03-25 09:44:22'),
(44, 3, 'sess_1774356639252_mu6fhw1a1', 'ou est situe la faculte des sciences?', 'La Faculté des Sciences de l\'Université de Douala est située sur le campus de **PK17**.', 'informations', '2026-03-25 09:51:00'),
(45, 3, 'sess_1774356639252_mu6fhw1a1', 'quels sont ses differents campus?', 'L\'Université de Douala est une université multi-sites, répartie sur plusieurs campus dans la ville de Douala. La Faculté des Sciences est spécifiquement située sur le campus de **Ndogbong**.\r\n\r\nVoici les différents campus de l\'Université de Douala :\r\n*   **Campus Bassa (Cité Sic)** : Il s\'agit du campus principal, abritant l\'École Supérieure des Sciences Économiques et Commerciales (ESSEC), la Faculté des Sciences Juridiques et Commerciales, la Faculté des Sciences Économiques, la Faculté de Génie Industriel et la Faculté de Médecine.\r\n*   **Campus Ndogbong** : Ce campus accueille l\'Institut Universitaire de Technologie (IUT), l\'École Normale Supérieure d\'Enseignement Technique (ENSET), la **Faculté des Sciences (FS)**, la Faculté de Génie Industriel (FGI) et la Faculté de Médecine et des Sciences Pharmaceutiques (FMSP).\r\n*   **Campus Akwa** : Il abrite l\'École Doctorale, le Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ) et l\'Académie Internet.\r\n*   **Campus Nkongsamba** : Ce site loge l\'Institut des Beaux-Arts (IBA).\r\n*   **Campus Yabassi** : Il accueille l\'Institut des Sciences Halieutiques (ISH).\r\n*   **Campus Logbessou** : La construction de ce campus a débuté en 2011 et est destinée à la Faculté de Médecine et des Sciences Pharmaceutiques (FMSP) et à la Faculté de Génie Industriel (FGI).', 'informations', '2026-03-25 09:51:24'),
(46, 3, 'sess_1774356639252_mu6fhw1a1', 'quels sont les enseignants de la facultés des sciences?', 'Il n\'existe pas de liste publique exhaustive et constamment mise à jour de tous les enseignants de la Faculté des Sciences de l\'Université de Douala.\r\n\r\nCependant, la Faculté des Sciences est organisée en plusieurs départements, et chaque département compte son propre corps enseignant. Pour obtenir une liste précise et actuelle des enseignants par département, il est recommandé de :\r\n\r\n*   **Consulter le site web officiel de la Faculté des Sciences de l\'Université de Douala.** Les sites web des facultés sont généralement les sources les plus fiables pour ce type d\'information.\r\n*   **Contacter directement la scolarité ou l\'administration de la Faculté des Sciences.** Ils pourront vous fournir les informations les plus à jour.\r\n\r\nJe peux vous donner des exemples de professeurs qui ont été mentionnés dans des documents publics ou des communications, mais cette liste n\'est pas exhaustive et peut ne pas être entièrement à jour :\r\n\r\n*   Monsieur YOMB Jacques (Maître de Conférences et Chef de Département)\r\n*   Monsieur MAPOURE NJANKOUO Yacouba (Professeur et Vice-Doyen chargé de la Programmation et du Suivi des Activités Académiques)\r\n*   Monsieur DOUMBE Jacques (Maître de Conférences et Chef de Département)\r\n*   Madame NGOUADJIEU Evelyne (Maître de Conférences)\r\n*   Annette Angoua Nguéa (Professeur)\r\n*   Assako Assako René Joly\r\n*   Thomas Atenga\r\n*   Samuel Bowong Tsakou\r\n\r\nPour des informations spécifiques sur les enseignants d\'un département particulier, je vous encourage vivement à vous référer aux canaux officiels de la Faculté.', 'enseignants', '2026-03-25 09:52:07'),
(47, 3, 'sess_1774356639252_mu6fhw1a1', 'comment se passe les compositions au sein de la Facultes de Sciences?', 'Les compositions (examens) à la Faculté des Sciences de l\'Université de Douala se déroulent selon des modalités précises :\r\n\r\n*   **Conditions d\'accès aux salles d\'examen** : Pour être autorisé à composer, l\'étudiant doit impérativement avoir réglé au moins deux tranches des droits universitaires ou des frais de formation et présenter les reçus et quitus probants de ces paiements. Une photocopie de chaque quitus et reçu est souvent demandée par l\'équipe de contrôle.\r\n*   **Pièce d\'identité** : La présentation d\'une pièce d\'identification en cours de validité, portant la photo de l\'étudiant (comme le formulaire d\'inscription/réinscription téléchargé), est obligatoire.\r\n*   **Interdiction d\'appareils électroniques** : Les téléphones portables et tout autre dispositif électronique compromettant (comme les montres connectées) sont strictement interdits dans les salles d\'examen.\r\n*   **Unités d\'Enseignement (UE)** : Les étudiants composent uniquement sur les Unités d\'Enseignement (UE) qu\'ils ont sélectionnées lors de leur inscription académique pour le semestre en cours. Il n\'y a pas d\'examens pour les UE non sélectionnées.\r\n*   **Calendrier et listes** : Les examens de fin de semestre sont planifiés et un calendrier est communiqué aux étudiants. Des listes des étudiants autorisés à prendre part aux examens sont également publiées par domaine/parcours.\r\n*   **Périodicité** : Les examens ont lieu généralement à la fin de chaque semestre.', 'cours', '2026-03-25 09:52:54'),
(48, 3, 'sess_1774356639252_mu6fhw1a1', 'quels sont les unites d&#039;enseignements pour les filieres informatiques niveau 1', 'Pour la filière Informatique de niveau 1 (Licence 1) à la Faculté des Sciences de l\'Université de Douala, les Unités d\'Enseignement (UE) comprennent des matières fondamentales, complémentaires et optionnelles.\r\n\r\nVoici une liste des UE généralement proposées:\r\n\r\n**Unités d\'Enseignement Fondamentales :**\r\n*   Introduction à l\'algorithme (INF 111)\r\n*   Architecture des ordinateurs (INF 121)\r\n*   Programmation structurée (C ou Python) (INF 131)\r\n*   Analyse 1 : analyse de la droite vectorielle réelle (MAT 121)\r\n*   Introduction à la programmation fonctionnelle (INF 112)\r\n*   Introduction aux réseaux (INF 122)\r\n*   Introduction aux systèmes d\'exploitation (INF 132)\r\n*   Algèbre linéaire (MAT 112)\r\n\r\n**Unités d\'Enseignement Complémentaires :**\r\n*   Éducation civique et éthique (INF 141)\r\n*   Formation bilingue 1 (INF 142)\r\n\r\n**Unités d\'Enseignement Optionnelles (au choix) :**\r\n*   Électrostatique (INF 151)\r\n*   Introduction au droit (INF 161)\r\n*   Programmation web statique (INF 171)\r\n*   Électronique numérique (INF 152)\r\n*   Programmation C++ (INF 162)\r\n*   Mécanique du point (INF 172)\r\n\r\nChaque UE a un nombre de crédits associé, généralement 6 pour les fondamentales et 3 pour les complémentaires et optionnelles.', 'cours', '2026-03-25 09:53:49'),
(49, 3, 'sess_1774356639252_mu6fhw1a1', 'comment faire pour valider une matière dans cette facultés?', 'Pour valider une matière (Unité d\'Enseignement - UE) à la Faculté des Sciences de l\'Université de Douala, vous devez généralement remplir les conditions suivantes :\r\n\r\n1.  **Obtenir la moyenne requise :** La validation d\'une UE se fait généralement en obtenant une moyenne minimale de **10/20** (dix sur vingt) sur l\'ensemble des évaluations de cette UE. Cette moyenne prend en compte les différentes composantes de l\'évaluation.\r\n\r\n2.  **Composantes de l\'évaluation :** La note finale d\'une UE est souvent une combinaison de plusieurs éléments :\r\n    *   **Contrôles Continus (CC) :** Il s\'agit d\'évaluations effectuées pendant le semestre (interrogations, devoirs, exposés, travaux pratiques, projets, etc.). Ils comptent généralement pour un certain pourcentage de la note finale (par exemple, 30% ou 40%).\r\n    *   **Examen Final (EF) :** C\'est l\'épreuve principale qui a lieu à la fin du semestre. Elle compte pour le pourcentage restant de la note finale (par exemple, 60% ou 70%).\r\n\r\n    La formule de calcul de la note finale est généralement : **Note Finale = (Poids CC x Note CC) + (Poids EF x Note EF)**.\r\n\r\n3.  **Rattrapages (Seconde Session) :** Si vous n\'atteignez pas la moyenne de 10/20 à l\'issue de la première session d\'examen pour une UE, vous avez généralement droit à une **seconde session (rattrapage)**. Pour cette seconde session, seule la note de l\'examen final est généralement prise en compte pour le calcul de la nouvelle moyenne de l\'UE. Si vous validez l\'UE au rattrapage, la note maximale qui peut être attribuée est souvent plafonnée à 10/20, même si vous obtenez une note supérieure.\r\n\r\n4.  **Compensation :** Dans le système LMD (Licence, Master, Doctorat), il existe souvent un mécanisme de **compensation** entre les Unités d\'Enseignement au sein d\'un même semestre, ou parfois entre semestres. Cela signifie que si vous avez une note légèrement inférieure à 10/20 dans une UE, mais que vous avez de très bonnes notes dans d\'autres UE du même semestre, la moyenne générale du semestre peut vous permettre de valider l\'UE en question, même si sa note individuelle est inférieure à 10/20. Les règles de compensation sont spécifiques à chaque établissement et sont définies dans le règlement pédagogique.\r\n\r\nIl est crucial de consulter le **règlement pédagogique** de la Faculté des Sciences pour connaître les modalités exactes de validation des UE, les coefficients des différentes évaluations et les règles de compensation spécifiques à votre filière et à votre année d\'étude.', 'cours', '2026-03-25 09:55:13'),
(50, 3, 'sess_1774356639252_mu6fhw1a1', 'quels sont les laboratoires de cette facultes?', 'La Faculté des Sciences de l\'Université de Douala abrite plusieurs laboratoires de recherche. Voici quelques-uns d\'entre eux :\r\n\r\n*   **Laboratoire de Biologie et Physiologie Animale**\r\n*   **Laboratoire d\'Informatique Appliquée (LIA)** : Ce laboratoire est un centre de recherche multidisciplinaire dédié à l\'étude et au développement de solutions innovantes en informatique. Il est organisé autour d\'équipes de recherche telles que l\'équipe ISDM (Intelligent & Sustainable Decision Making) et l\'équipe d\'imagerie et signal.\r\n*   **Laboratoire des Géosciences, ressources…**\r\n*   **CEPAMOQ (Centre de Physique Atomique Moléculaire et Optique Quantique)**\r\n*   **LTSA (Laboratoire de Traitement du Signal et des Applications)** : Créé en 2017, ce laboratoire de recherche appartient à l\'Unité de Formation Doctorale des Sciences Appliquées (UFD-SCA) de l\'École Doctorale des Sciences Fondamentales et Appliquées (EDOSFA) de l\'Université de Douala.', 'informations', '2026-03-25 09:56:43'),
(51, 3, 'sess_1774356639252_mu6fhw1a1', 'tu connais le laboratoire ISDM de Pr. Moskolai dans la Facultes des Sciences?', 'Oui, je connais le laboratoire ISDM et le Professeur Justin Moskolaï Ngossaha.\r\n\r\nL\'équipe **ISDM (Intelligent & Sustainable Decision Making)** est une équipe de recherche interdisciplinaire rattachée au **Laboratoire d\'Informatique Appliquée (LIA)** du Département de Mathématiques et Informatique de la Faculté des Sciences de l\'Université de Douala.\r\n\r\nLe **Professeur Justin MOSKOLAI NGOSSAHA** est le **Coordinateur de l\'équipe de recherche ISDM**. Il est Maître de Conférences et chercheur au Département de Mathématiques et Informatique de la Faculté des Sciences de l\'Université de Douala. Ses activités de recherche se concentrent sur l\'intelligence artificielle, les systèmes d\'aide à la décision, l\'interopérabilité, l\'ingénierie des connaissances, les systèmes de transport et les systèmes durables.', 'informations', '2026-03-25 09:57:25'),
(52, 3, 'sess_1774356639252_mu6fhw1a1', 'qui gere l&#039;equipe d&#039;imagerie et signal?', 'L\'équipe d\'imagerie et signal au sein du Laboratoire d\'Informatique Appliquée (LIA) de la Faculté des Sciences de l\'Université de Douala est supervisée par le **Dr. Joseph MVOGO NGONO**.', 'informations', '2026-03-25 09:58:51'),
(53, 3, 'sess_1774356639252_mu6fhw1a1', 'et Dr Noumsi appartient a quel equipe?', 'Le Dr Vigny NOUMSI WOGUIA est l\'un des **Directeurs du Laboratoire d\'Informatique Appliquée (LIA)** à la Faculté des Sciences de l\'Université de Douala.\r\n\r\nLe LIA est le laboratoire qui abrite les équipes de recherche ISDM et l\'équipe d\'imagerie et signal.', 'informations', '2026-03-25 09:59:12'),
(54, 3, 'sess_1774356639252_mu6fhw1a1', 'parle moi de Pr. Justin Moskolai, je veux une description complete', 'Le Professeur Justin Moskolaï Ngossaha est une figure éminente de la Faculté des Sciences de l\'Université de Douala, reconnu pour ses contributions significatives dans le domaine de l\'informatique et des systèmes d\'aide à la décision.\r\n\r\nVoici une description complète de son profil :\r\n\r\n**Position Actuelle et Affiliation :**\r\nLe Professeur Justin Moskolaï Ngossaha est **Maître de Conférences** et chercheur au **Département de Mathématiques et Informatique** de la Faculté des Sciences de l\'Université de Douala. Il est également le **Coordinateur de l\'équipe de recherche ISDM (Intelligent & Sustainable Decision Making)**, qui fait partie du Laboratoire d\'Informatique Appliquée (LIA) de la même faculté.\r\n\r\n**Formation Académique :**\r\nIl est titulaire d\'un **Doctorat en Informatique** obtenu à l\'Institut National Polytechnique de Toulouse (INPT) en France. Il est également qualifié CNU de France (27ème session).\r\n\r\n**Domaines de Recherche :**\r\nSes activités de recherche sont vastes et se concentrent principalement sur :\r\n*   **Intelligence Artificielle**\r\n*   **Systèmes d\'Aide à la Décision**\r\n*   **Interopérabilité**\r\n*   **Ingénierie des Connaissances**\r\n*   **Systèmes de Transport**\r\n*   **Systèmes Durables**\r\n*   **Gestion des connaissances**\r\n*   **Flou (Fuzziness)**\r\n\r\n**Contributions et Focus Spécifiques :**\r\nLe Professeur Moskolaï Ngossaha s\'intéresse particulièrement à l\'amélioration de la conception et de la mise en œuvre de **systèmes de mobilité urbaine durable**, notamment dans le contexte des pays en développement. Ses travaux visent à utiliser la gestion et l\'analyse des données urbaines pour améliorer la qualité de vie, l\'environnement et les systèmes de mobilité. Il explore comment les gestionnaires urbains peuvent utiliser ces données pour améliorer la mobilité urbaine, en se concentrant sur l\'élicitation des connaissances et l\'évaluation de la durabilité d\'un système de mobilité urbaine par la simulation, afin de guider la prise de décision vers la mise en œuvre de \"Smart Cities\".\r\n\r\nIl a notamment développé des méthodologies intégrant des approches de **décision multicritères floues** pour évaluer et sélectionner les services de mobilité urbaine les plus durables et écologiquement responsables. Ses recherches abordent également l\'optimisation des systèmes de mobilité urbaine cyber-physiques dans les pays en développement.\r\n\r\n**Publications et Collaborations :**\r\nLe Professeur Moskolaï Ngossaha est un auteur prolifique, avec de nombreuses publications dans des revues et conférences scientifiques. Il collabore avec d\'autres chercheurs nationaux et internationaux sur divers projets.', 'informations', '2026-03-25 09:59:55'),
(55, 3, 'sess_1774356639252_mu6fhw1a1', 'tu peux me donner quels autres informations sur la Faculté des Sciences?', 'La Faculté des Sciences (FS) de l\'Université de Douala est un pôle d\'excellence pour l\'enseignement et la recherche scientifique au Cameroun. Voici quelques informations supplémentaires :\r\n\r\n**Localisation et Infrastructures :**\r\nLa Faculté des Sciences est principalement située sur le **Campus de PK17** à Douala, où se trouvent le Décanat, les salles de cours, les laboratoires et un amphithéâtre. Elle dispose également d\'un amphithéâtre au campus I et bénéficie de locaux à l\'ancien Rectorat à Akwa, qui abritent notamment le CEPAMOQ (Centre de Physique Atomique Moléculaire et Optique Quantique). La Faculté partage aussi des salles de cours et deux amphithéâtres de 500 places avec d\'autres facultés au campus II à Ndogbong.\r\n\r\n**Cycles d\'Études :**\r\nLa Faculté des Sciences propose les trois cycles du système LMD (Licence, Master, Doctorat) :\r\n*   **Premier Cycle (Licence) :** D\'une durée de trois ans (six semestres), il couvre les niveaux I à III et comprend des enseignements fondamentaux, de formation bilingue et de professionnalisation.\r\n*   **Deuxième Cycle (Master) :** D\'une durée de deux ans (quatre semestres), il couvre les niveaux IV et V.\r\n*   **Troisième Cycle (Doctorat) :** Le CEPAMOQ, par exemple, assure une formation doctorale à partir du Master 2 en Physique de la Matière et du Rayonnement.\r\n\r\n**Départements :**\r\nLa Faculté des Sciences est structurée en plusieurs départements, parmi lesquels on retrouve :\r\n*   Biologie des organismes animaux\r\n*   Biologie des organismes végétaux\r\n*   Biochimie\r\n*   Sciences de la Terre\r\n*   Physique\r\n*   Mathématiques et Informatique\r\n*   Chimie\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\n**Conditions d\'Admission :**\r\nL\'inscription à la Faculté des Sciences de l\'Université de Douala est généralement ouverte aux titulaires des BAC C, D, E, F et TI, ainsi qu\'aux titulaires du GCE \"AL\" obtenu en au moins deux matières scientifiques, et du GCE \"OL\" obtenu en quatre matières dont au moins deux scientifiques (Mathématiques, Physique, Chimie, Biologie, Informatique). Des conditions supplémentaires peuvent être requises en fonction de la filière sollicitée.\r\n\r\n**Formations :**\r\nEn plus des filières classiques, la Faculté des Sciences propose également des filières professionnelles, notamment des Diplômes d\'Études Universitaires Professionnelles (DEUP), des Licences Professionnelles et des Masters Professionnels dans des domaines variés comme le Génie Informatique et Décisionnel, la Microbiologie Médicale, la Production, transformation et conservation des produits agricoles, les Techniques de Laboratoires, la Qualité Sécurité Environnement (QSE), les Biotechnologies, Diététique et Nutrition, et les Méthodes Informatiques Appliquées à la Gestion des Entreprises (MIAGE).\r\n\r\n**Mission et Objectifs :**\r\nLa mission de l\'Université de Douala, dont fait partie la Faculté des Sciences, est l\'élaboration et la transmission des connaissances, le développement de la recherche et la formation des hommes. Elle vise à procurer l\'accès à la formation supérieure à tous ceux qui en ont la vocation et la capacité, et à contribuer au développement et à la promotion sociale et culturelle. L\'objectif est de fournir un environnement sûr et heureux aux étudiants, où ils pourront s\'épanouir tout en acquérant les connaissances nécessaires pour leurs carrières professionnelles.', 'informations', '2026-03-25 10:01:42'),
(56, 3, 'sess_1774356639252_mu6fhw1a1', 'bonjour', 'Bonjour ! Comment puis-je vous aider aujourd\'hui ?\r\n', 'informations', '2026-03-25 10:09:56'),
(57, 3, 'sess_1774356639252_mu6fhw1a1', 'parle moi de Pr justin moskolai', 'On a déjà abordé le sujet du Pr. Justin Moskolaï en détail. Que souhaitez-vous savoir de plus ? Pour vous rafraîchir la mémoire, voici un résumé :\r\n\r\nLe Professeur Justin Moskolaï Ngossaha est Maître de Conférences et chercheur en Informatique à la Faculté des Sciences de l\'Université de Douala. Il est un expert en Intelligence Artificielle, Systèmes d\'Aide à la Décision, et Mobilité Urbaine Durable. Il dirige l\'équipe de recherche ISDM et est qualifié CNU de France.\r\n\r\nQu\'est-ce qui vous intéresse plus particulièrement chez le Prof. Moskolaï ? Peut-être concernant ses projets actuels, ses publications spécifiques, ou son parcours ?\r\n', 'informations', '2026-03-25 10:10:34'),
(58, 3, 'sess_1774282050106_tz5gey9ck', 'qui est le doyen de la facultés des sciences ?', 'La Doyenne de la Faculté des Sciences de l\'Université de Douala est le **Professeur Marie Joseph Ntamak**.', 'informations', '2026-03-26 10:22:08'),
(60, 3, 'sess_1774282050106_tz5gey9ck', 'quels sont les conditions d\'eligibilite en master ?', 'Pour être éligible à un Master à la Faculté des Sciences de l\'Université de Douala, les conditions générales sont les suivantes :\r\n\r\n1.  **Diplôme requis** : Il faut être titulaire d\'une Licence (BAC+3) ou d\'un diplôme équivalent dans la spécialité correspondante au Master visé. Pour les Masters professionnels, un niveau BAC+3 ou équivalent est requis.\r\n2.  **Étude de dossier** : L\'admission se fait généralement sur étude de dossier.\r\n3.  **Dossier de candidature** : Le dossier comprend typiquement :\r\n    *   Des photocopies de l\'acte de naissance (dont une légalisée).\r\n    *   Des photocopies du diplôme de Licence ou équivalent (dont une légalisée).\r\n    *   Les relevés du dernier diplôme obtenu.\r\n    *   Une lettre de motivation et un CV peuvent être demandés.\r\n    *   Des photos d\'identité.\r\n    *   Une fiche d\'inscription.\r\n    *   Un reçu de paiement des frais d\'étude de dossier.\r\n4.  **Frais de pré-inscription** : Des frais de pré-inscription sont à payer, par exemple 10 000 FCFA à la UBA pour la pré-inscription en ligne.\r\n5.  **Processus de pré-inscription en ligne** : La pré-inscription se fait en ligne sur des plateformes dédiées comme www.systhag-online.cm ou www.facscienceunivdouala.cm.\r\n6.  **Sélection** : Après l\'étude des dossiers, les listes des étudiants pré-inscrits sont affichées.\r\n\r\nIl est important de noter que les conditions spécifiques peuvent varier légèrement en fonction de la filière de Master (Master Recherche ou Master Professionnel) et du département. Il est toujours recommandé de consulter les annonces officielles de la Faculté des Sciences ou de contacter directement le département concerné pour les informations les plus précises et à jour.', 'informations', '2026-03-26 10:23:56'),
(67, 3, 'sess_1774282050106_tz5gey9ck', 'qui travaille a la cellule informatique?', 'Je n\'ai pas trouvé d\'informations spécifiques sur les personnes travaillant dans une \"cellule informatique\" administrative ou de support technique pour l\'ensemble de la Faculté des Sciences de l\'Université de Douala.\r\n\r\nCependant, la Faculté des Sciences abrite le **Laboratoire d\'Informatique Appliquée (LIA)** et le **Département de Mathématiques et Informatique**, où travaillent des enseignants-chercheurs et des chercheurs dans le domaine de l\'informatique.\r\n\r\nAu sein du Laboratoire d\'Informatique Appliquée (LIA), on trouve notamment :\r\n*   **Dr. Joseph MVOGO NGONO** (Directeur)\r\n*   **Pr. Samuel BOWONG** (Directeur)\r\n*   **Dr Vigny NOUMSI WOGUIA** (Directeur)\r\n*   **Dr Justin MOKOLAI NGOSSAHA** (Superviseur de l\'équipe ISDM)\r\n*   **Dr Joseph MVONGO NGONO** (Superviseur de l\'équipe d\'imagerie et signal)\r\n\r\nL\'équipe de recherche ISDM (Intelligent & Sustainable Decision Making) du Département de Mathématiques et Informatique comprend également :\r\n*   **Pr. Justin MOSKOLAI** (Coordonnateur de l\'équipe de recherche)\r\n*   **Dr Rodrigue DJEUMEN** (Responsable des Projets)\r\n*   **Dr Bertrand MBAMA** (Responsable de la Coopération)\r\n*   **Dr Yannick MALONG** (Responsable de l\'innovation)\r\n\r\nSi votre question concerne le personnel technique ou administratif en charge de l\'infrastructure informatique ou du support aux utilisateurs pour la faculté, ces informations ne sont pas disponibles dans les résultats de ma recherche.', 'informations', '2026-03-26 11:16:32'),
(68, 3, 'sess_1774282050106_tz5gey9ck', 'Où se font les paiements des droits universitaires à la faculté des sciences ?', 'Les paiements des droits universitaires à la Faculté des Sciences de l\'Université de Douala se font principalement auprès de la **United Bank for Africa (UBA)**.\r\n\r\nUBA déploie des postes de paiement sur tous les campus pour faciliter ces transactions.\r\n\r\nLe processus général implique souvent une pré-inscription en ligne, suivie du paiement des frais (y compris les droits universitaires) à la banque, puis le téléchargement des quitus de paiement via les plateformes en ligne de l\'université.', 'informations', '2026-03-26 11:28:36'),
(69, 3, 'sess_1774282050106_tz5gey9ck', 'Parle moi de la faculté des sciences', 'La Faculté des Sciences (FS) de l\'Université de Douala, créée en 1993, est située sur le campus de PK17. Elle contribue à la mission globale de l\'Université de Douala, qui est l\'élaboration et la transmission des connaissances, le développement de la recherche et la formation des individus.\r\n\r\nLa Faculté des Sciences propose des formations réparties sur trois cycles : Licence, Master et Doctorat. Elle est structurée en plusieurs départements, notamment:\r\n*   Biochimie\r\n*   Biologie des Organismes Animaux\r\n*   Biologie des Organismes Végétaux\r\n*   Chimie\r\n*   Physique\r\n*   Sciences de la Terre\r\n*   Mathématiques-Informatique\r\n*   Centre de Physique Atomique Moléculaire et Optique Quantique (CEPAMOQ)\r\n\r\nElle offre des filières de formation classiques et professionnelles, avec des spécialités variées en Chimie, Géosciences, Mathématiques, Informatique, Biologie et Physique. Les conditions d\'admission requièrent généralement un BAC C, D, E, F ou TI, ou un GCE \"AL\" avec au moins deux matières scientifiques, ainsi qu\'un GCE \"OL\" avec quatre matières dont au moins deux scientifiques (Mathématiques, Physique, Chimie, Biologie, Informatique).', 'informations', '2026-03-28 11:05:04'),
(70, 3, 'sess_1774282050106_tz5gey9ck', 'Comment me preinscrire à la faculté des sciences ?', 'Pour te préinscrire à la Faculté des Sciences de l\'Université de Douala, voici les étapes à suivre, basées sur les informations disponibles:\r\n\r\n**1. Vérifier les conditions d\'admission :**\r\nAssure-toi de posséder le diplôme requis pour l\'admission à la Faculté des Sciences. Il s\'agit généralement d\'un Baccalauréat C, D, E, F, TI, ou un GCE AL scientifique avec au moins deux matières scientifiques, et un GCE OL avec au moins deux matières scientifiques (Mathématiques, Physique, Chimie, Biologie, Informatique). Pour les filières Mathématiques et Informatique, un Baccalauréat C ou E est souvent obligatoire, ou un Bac D avec une moyenne d\'au moins 12/20 en Mathématiques.\r\n\r\n**2. Effectuer la préinscription en ligne :**\r\nRends-toi sur la plateforme Systhag Online à l\'adresse : [http://www.systhag-online.cm:8080/SYSTHAG-ONLINE/](http://www.systhag-online.cm:8080/SYSTHAG-ONLINE/). Tu peux aussi trouver des liens sur le site de la Faculté des Sciences.\r\n\r\n**3. Payer les frais de préinscription et autres frais :**\r\nTu devras payer les frais de préinscription, les frais de visite médicale (et effectuer la visite médicale au centre médico-social de l\'Université de Douala), ainsi qu\'au moins la première tranche des droits universitaires. Ces paiements se font généralement auprès de la United Bank for Africa (UBA). Les frais de préinscription sont de 10 000 FCFA.\r\n\r\n**4. Scanner et importer les documents requis :**\r\nScanne les documents nécessaires et importe-les sur la plateforme. Les documents doivent être en format image lisible et ne pas dépasser 1 Mo. Voici la liste des documents à scanner:\r\n*   Photo portrait 4x4 lisible en couleur.\r\n*   Photocopie certifiée conforme de l\'acte de naissance (datant de moins de trois mois).\r\n*   Fiche de préinscription signée par l\'étudiant.\r\n*   Certificat médical délivré par le centre médico-social de l\'Université de Douala.\r\n*   Photocopie certifiée conforme du Probatoire ou GCE OL.\r\n*   Photocopie certifiée conforme du Baccalauréat ou GCE AL.\r\n*   Les reçus et quitus certifiés et validés de préinscription.\r\n*   Les reçus et quitus certifiés et validés d\'au moins la première tranche des droits universitaires (ou des deux tranches si tu as payé la totalité).\r\n*   Pour les candidats en Licence professionnelle, Master professionnel ou Master classique, soumets les relevés du dernier diplôme obtenu et le dernier diplôme en question à la place du Probatoire et du Baccalauréat.\r\n\r\n**5. Valider tes données :**\r\nUne fois tous les documents importés, clique sur le bouton \"valider\" pour enregistrer tes données.\r\n\r\n**6. Déposer le dossier physique :**\r\nAprès avoir soumis la version numérique, tu devras déposer une version physique de ton dossier au Campus 3 situé à PK17, selon un programme qui sera communiqué. Pour les candidats retenus, le dossier physique est à déposer auprès des secrétariats des départements situés au Campus 1 à Ange Raphaël, Bâtiment C.\r\n\r\nIl est important de noter que les dates de préinscription sont annoncées par un communiqué du Recteur de l\'Université, généralement à partir du mois de septembre de chaque année. Les pré-inscriptions pour l\'année académique 2025-2026 sont ouvertes tous les jours.\r\n\r\nPour toute erreur constatée (filière, niveau, nom, etc.), signale-le à la scolarité après le paiement des droits universitaires.', 'informations', '2026-03-28 11:05:48'),
(71, 3, 'sess_1774282050106_tz5gey9ck', 'Qui est le doyen de la Faculté des sciences ?', 'La Doyenne de la Faculté des Sciences de l\'Université de Douala est le **Professeur Marie Joseph Ntamak**.', 'informations', '2026-03-28 11:06:20');
INSERT INTO `conversations` (`id`, `user_id`, `session_id`, `message_user`, `reponse_ai`, `mode`, `date_created`) VALUES
(72, 3, 'sess_1774282050106_tz5gey9ck', 'Quels sont les unités d’enseignement pour les licence 1 en informatique ?', 'Pour la Licence 1 en Informatique à la Faculté des Sciences de l\'Université de Douala, les Unités d\'Enseignement (UE) sont réparties sur deux semestres et couvrent des domaines fondamentaux de l\'informatique et des mathématiques, ainsi que des compétences complémentaires.\r\n\r\nVoici une liste des principales Unités d\'Enseignement pour la Licence 1 en Informatique:\r\n\r\n**UE Fondamentales :**\r\n*   **INF 111 :** Introduction à l\'algorithme (6 crédits)\r\n*   **INF 121 :** Architecture des ordinateurs (6 crédits)\r\n*   **INF 131 :** Programmation structurée (C ou Python) (6 crédits)\r\n*   **MAT 121 :** Analyse 1 : analyse de la droite vectorielle réelle (6 crédits)\r\n*   **INF 112 :** Introduction à la programmation fonctionnelle (6 crédits)\r\n*   **INF 122 :** Introduction aux réseaux (6 crédits)\r\n*   **INF 132 :** Introduction aux systèmes d\'exploitation (6 crédits)\r\n*   **MAT 112 :** Algèbre linéaire (6 crédits)\r\n\r\n**UE Complémentaires :**\r\n*   **INF 141 :** Éducation civique et éthique (3 crédits)\r\n*   **INF 142 :** Formation bilingue 1 (3 crédits)\r\n\r\n**UE Optionnelles au choix (exemples) :**\r\n*   **INF 151 :** Électrostatique (3 crédits)\r\n*   **INF 161 :** Introduction au droit (3 crédits)\r\n*   **INF 171 :** Programmation web statique (3 crédits)\r\n*   **INF 152 :** Électronique numérique (3 crédits)\r\n*   **INF 162 :** Programmation C++ (3 crédits)\r\n*   **INF 172 :** Mécanique du point (3 crédits)\r\n\r\nCe programme vise à fournir aux étudiants une base solide en informatique et en mathématiques, essentielle pour la poursuite de leurs études dans le domaine.', 'informations', '2026-03-28 11:06:55'),
(73, 3, 'sess_1774282050106_tz5gey9ck', 'Parle moi des laboratoires de recherche de là facultés des sciences', 'La Faculté des Sciences de l\'Université de Douala abrite plusieurs laboratoires de recherche qui mènent des travaux fondamentaux et appliqués dans divers domaines scientifiques. Voici quelques-uns de ces laboratoires :\r\n\r\n*   **Laboratoire des Géosciences, ressources naturelles et environnement** : Ce laboratoire se concentre sur la recherche fondamentale et appliquée concernant les matériaux de l\'écorce terrestre et les combustibles fossiles, en intégrant une dimension environnementale. Il est structuré autour de deux grands axes de recherche avec cinq équipes.\r\n\r\n*   **Laboratoire d\'Informatique Appliquée (LIA)** : Le LIA est un centre de recherche multidisciplinaire dédié à l\'étude et au développement de solutions innovantes en informatique. Ses activités couvrent des domaines clés pour répondre aux défis technologiques et sociétaux actuels, avec un engagement à produire des recherches de pointe et à former des experts. Il est organisé autour de deux équipes de recherche :\r\n    *   L\'équipe **ISDM (Intelligent & Sustainable Decision Making)**, supervisée par le Dr Justin MOKOLAI NGOSSAHA.\r\n    *   L\'équipe d\'**Imagerie et Signal**, supervisée par le Dr Joseph MVONGO NGONO.\r\n    Le LIA coordonne également les formations de master et les thèses.\r\n\r\n*   **Laboratoire de Biologie et Physiologie Animale** : Ce laboratoire mène des recherches sur la valorisation des sols et des matériaux, la dépollution des villes, et le traçage géochimique. Il est impliqué dans des projets tels que la résorption de la pollution urbaine et la caractérisation des ressources du sous-sol.\r\n\r\n*   **Laboratoire de Chimie** : Bien que les détails spécifiques de ses axes de recherche ne soient pas entièrement précisés dans les résultats, il est mentionné comme un laboratoire de la Faculté des Sciences de l\'Université de Douala.\r\n\r\nEn outre, d\'autres laboratoires sont associés à l\'Université de Douala et contribuent à la recherche scientifique, bien que leur rattachement direct à la Faculté des Sciences ne soit pas toujours explicitement détaillé dans toutes les sources :\r\n\r\n*   **Laboratoire de Technologies et Sciences Appliquées (LTSA)** : Créé en 2017, le LTSA est un laboratoire de recherche appartenant à l\'Unité de Formation Doctorale des Sciences Appliquées (UFD-SCA) de l\'École Doctorale des Sciences Fondamentales et Appliquées (EDOSFA) de l\'Université de Douala. Il est hébergé à l\'Institut Universitaire de Technologies (IUT) de Douala.\r\n\r\n*   **IBHI Lab** : Ce laboratoire est également associé à l\'Université de Douala et mène des activités de recherche, comme en témoignent ses actualités et publications.', 'informations', '2026-03-28 11:07:37'),
(74, 3, 'sess_1774282050106_tz5gey9ck', 'Parle mon du laboratoire ISDM', 'Le laboratoire ISDM, acronyme de \"Intelligent & Sustainable Decision Making\", est une équipe de recherche interdisciplinaire rattachée au Département de Mathématiques et Informatique de la Faculté des Sciences de l\'Université de Douala. Il fait partie du Laboratoire d\'Informatique Appliquée (LIA).\r\n\r\nL\'équipe ISDM est composée d\'enseignants-chercheurs et de jeunes chercheurs passionnés, animés par une forte culture scientifique et un engagement sociétal.\r\n\r\n**Axes de recherche :**\r\nLes activités scientifiques de l\'équipe ISDM s\'articulent autour de cinq axes de recherche interconnectés, à l\'interface de l\'intelligence artificielle, de la science des données et de la durabilité des systèmes complexes :\r\n*   **Intelligence Artificielle Urbaine :** Développement de modèles et d\'outils d\'IA pour la planification, la gestion et l\'évolution intelligente des villes africaines, en intégrant les dimensions sociales, économiques et environnementales.\r\n*   **Ingénierie des Connaissances et Systèmes d\'Interopérabilité :** Conception de méthodes et de technologies pour la capture, la modélisation, le partage et l\'exploitation des connaissances, favorisant l\'interopérabilité entre systèmes hétérogènes et le pilotage coordonné de services urbains et territoriaux.\r\n*   **Systèmes de Communication Durables et IoT (Internet des Objets) :** Recherche sur les systèmes de communication durables et l\'Internet des Objets.\r\n*   **Conception de Systèmes Complexes et Aide à la Décision :** Modélisation et structuration de systèmes intelligents capables de fonctionner efficacement dans des environnements dynamiques, contraints et incertains. Cet axe intègre des outils issus de la théorie des jeux et de l\'aide à la décision multicritère (ADM) pour traiter des décisions complexes.\r\n*   **Jumeaux Numériques et Process Mining :** Exploration des jumeaux numériques et du \"process mining\".\r\n\r\n**Vision et impact :**\r\nLes recherches de l\'équipe ISDM visent à concevoir des solutions intelligentes, robustes et durables pour répondre aux grands défis du développement en Afrique. Cela inclut la transformation numérique des villes et des territoires, l\'amélioration de la gouvernance et de la prise de décision, l\'optimisation des ressources et des infrastructures, ainsi que la promotion d\'un développement inclusif et résilient.\r\n\r\n**Membres clés :**\r\n*   **Pr. Justin MOSKOLAI :** Coordonnateur de l\'équipe de recherche.\r\n*   **Dr Rodrigue DJEUMEN :** Responsable des Projets.\r\n*   **Dr Bertrand MBAMA :** Responsable de la Coopération.\r\n*   **Dr Yannick MALONG :** Responsable de l\'innovation.\r\n*   **Pr. Samuel BOWONG :** Responsable du Département Maths-Info.\r\n\r\nL\'équipe ISDM est également impliquée dans la coordination des formations de master et des thèses au sein du Laboratoire d\'Informatique Appliquée (LIA).', 'informations', '2026-03-28 11:08:08'),
(85, 3, 'sess_1775162830559_pqvxqd2g8', 'Qui est mr ndje ?', 'Monsieur Ndje, de son nom complet Yves Jonathan Ndje, est le maréchal de la Faculté des Sciences.', 'informations', '2026-04-02 20:51:24'),
(86, 3, 'sess_1774282050106_tz5gey9ck', 'Parle moi  du laboratoire ISDM', 'Le laboratoire ISDM, acronyme de \"Intelligent & Sustainable Decision Making\", est une équipe de recherche interdisciplinaire rattachée au Département de Mathématiques et Informatique de la Faculté des Sciences de l\'Université de Douala. Il fait partie du Laboratoire d\'Informatique Appliquée (LIA).\r\n\r\nL\'équipe ISDM est composée d\'enseignants-chercheurs et de jeunes chercheurs passionnés, animés par une forte culture scientifique et un engagement sociétal.\r\n\r\n**Axes de recherche :**\r\nLes activités scientifiques de l\'équipe ISDM s\'articulent autour de cinq axes de recherche interconnectés, à l\'interface de l\'intelligence artificielle, de la science des données et de la durabilité des systèmes complexes :\r\n*   **Intelligence Artificielle Urbaine :** Développement de modèles et d\'outils d\'IA pour la planification, la gestion et l\'évolution intelligente des villes africaines, en intégrant les dimensions sociales, économiques et environnementales.\r\n*   **Ingénierie des Connaissances et Systèmes d\'Interopérabilité :** Conception de méthodes et de technologies pour la capture, la modélisation, le partage et l\'exploitation des connaissances, favorisant l\'interopérabilité entre systèmes hétérogènes et le pilotage coordonné de services urbains et territoriaux.\r\n*   **Systèmes de Communication Durables et IoT (Internet des Objets) :** Recherche sur les systèmes de communication durables et l\'Internet des Objets.\r\n*   **Conception de Systèmes Complexes et Aide à la Décision :** Modélisation et structuration de systèmes intelligents capables de fonctionner efficacement dans des environnements dynamiques, contraints et incertains. Cet axe intègre des outils issus de la théorie des jeux et de l\'aide à la décision multicritère (ADM) pour traiter des décisions complexes.\r\n*   **Jumeaux Numériques et Process Mining :** Exploration des jumeaux numériques et du \"process mining\".\r\n\r\n**Vision et impact :**\r\nLes recherches de l\'équipe ISDM visent à concevoir des solutions intelligentes, robustes et durables pour répondre aux grands défis du développement en Afrique. Cela inclut la transformation numérique des villes et des territoires, l\'amélioration de la gouvernance et de la prise de décision, l\'optimisation des ressources et des infrastructures, ainsi que la promotion d\'un développement inclusif et résilient.\r\n\r\n**Membres clés :**\r\n*   **Pr. Justin MOSKOLAI :** Coordonnateur de l\'équipe de recherche.\r\n*   **Dr Rodrigue DJEUMEN :** Responsable des Projets.\r\n*   **Dr Bertrand MBAMA :** Responsable de la Coopération.\r\n*   **Dr Yannick MALONG :** Responsable de l\'innovation.\r\n*   **Pr. Samuel BOWONG :** Responsable du Département Maths-Info.\r\n\r\nL\'équipe ISDM est également impliquée dans la coordination des formations de master et des thèses au sein du Laboratoire d\'Informatique Appliquée (LIA).', 'informations', '2026-04-07 04:37:13'),
(87, 3, 'sess_1774282050106_tz5gey9ck', 'Parle moi du laboratoire ISDM', 'Le laboratoire ISDM, acronyme de \"Intelligent & Sustainable Decision Making\", est une équipe de recherche interdisciplinaire rattachée au Département de Mathématiques et Informatique de la Faculté des Sciences de l\'Université de Douala. Il fait partie du Laboratoire d\'Informatique Appliquée (LIA).\r\n\r\nL\'équipe ISDM est composée d\'enseignants-chercheurs et de jeunes chercheurs passionnés, animés par une forte culture scientifique et un engagement sociétal.\r\n\r\n**Axes de recherche :**\r\nLes activités scientifiques de l\'équipe ISDM s\'articulent autour de cinq axes de recherche interconnectés, à l\'interface de l\'intelligence artificielle, de la science des données et de la durabilité des systèmes complexes :\r\n*   **Intelligence Artificielle Urbaine :** Développement de modèles et d\'outils d\'IA pour la planification, la gestion et l\'évolution intelligente des villes africaines, en intégrant les dimensions sociales, économiques et environnementales.\r\n*   **Ingénierie des Connaissances et Systèmes d\'Interopérabilité :** Conception de méthodes et de technologies pour la capture, la modélisation, le partage et l\'exploitation des connaissances, favorisant l\'interopérabilité entre systèmes hétérogènes et le pilotage coordonné de services urbains et territoriaux.\r\n*   **Systèmes de Communication Durables et IoT (Internet des Objets) :** Recherche sur les systèmes de communication durables et l\'Internet des Objets.\r\n*   **Conception de Systèmes Complexes et Aide à la Décision :** Modélisation et structuration de systèmes intelligents capables de fonctionner efficacement dans des environnements dynamiques, contraints et incertains. Cet axe intègre des outils issus de la théorie des jeux et de l\'aide à la décision multicritère (ADM) pour traiter des décisions complexes.\r\n*   **Jumeaux Numériques et Process Mining :** Exploration des jumeaux numériques et du \"process mining\".\r\n\r\n**Vision et impact :**\r\nLes recherches de l\'équipe ISDM visent à concevoir des solutions intelligentes, robustes et durables pour répondre aux grands défis du développement en Afrique. Cela inclut la transformation numérique des villes et des territoires, l\'amélioration de la gouvernance et de la prise de décision, l\'optimisation des ressources et des infrastructures, ainsi que la promotion d\'un développement inclusif et résilient.\r\n\r\n**Membres clés :**\r\n*   **Pr. Justin MOSKOLAI :** Coordonnateur de l\'équipe de recherche.\r\n*   **Dr Rodrigue DJEUMEN :** Responsable des Projets.\r\n*   **Dr Bertrand MBAMA :** Responsable de la Coopération.\r\n*   **Dr Yannick MALONG :** Responsable de l\'innovation.\r\n*   **Pr. Samuel BOWONG :** Responsable du Département Maths-Info.\r\n\r\nL\'équipe ISDM est également impliquée dans la coordination des formations de master et des thèses au sein du Laboratoire d\'Informatique Appliquée (LIA).', 'informations', '2026-04-07 04:41:23'),
