INSERT INTO `equipe_projet` (`id`, `nom`, `role`, `photo_url`, `linkedin`) VALUES
(1, 'Yann FOKA', 'RobIA Tech Team', 'public/images/yann.jpeg', 'https://www.linkedin.com/in/yann-brondon-foka-maghen-687419292/'),
INSERT INTO `faculte_infos` (`id`, `titre`, `categorie`, `contenu`, `mots_cles`, `date_created`) VALUES
(1, 'Procedure de preinscription', 'Inscription', 'La preinscription s\'effectue en ligne sur les sites officiels SYSTHAG Online ou FS-Univ-Dla. Elle repose sur une etude de dossier', 'preinscription, en ligne, SYSTHAG, dossier, inscription', '2026-03-25 20:53:45'),
(2, 'Dossier d\'inscription L1', 'Inscription', 'Le dossier comprend : photocopies certifiées du Baccalauréat scientifique, de l\'acte de naissance (-3 mois), un certificat médical du Centre Médico-Social de l\'UDo, et une photo 4x4.', 'dossier, L1, baccalaureat, naissance, certificat medical, inscription', '2026-03-25 20:53:45'),
(3, 'Calendrier des Inscriptions', 'Inscription', 'Les inscriptions en ligne sont généralement ouvertes du 25 août au 30 septembre pour les nouveaux étudiants, et jusqu\'au 31 octobre pour les anciens.', 'calendrier, dates, inscriptions, aout, septembre, octobre', '2026-03-25 20:53:45'),
(4, 'Filieres profesionnelles', 'Formations', 'La faculté propose des Licences Pro comme LIDA (Informatique Décisionnelle), LIME (Microbiologie Médicale), AGRI-PRO (Agriculture) et TL (Techniques de Laboratoire).', 'licence pro, LIDA, LIME, AGRI-PRO, TL, filieres', '2026-03-25 20:53:45'),
(5, 'Cycles Master et Doctorat', 'Formations', 'Masters en MIAGE, QSE, Pétromine, et Doctorat (PhD) dans l\'École Doctorale des Sciences Fondamentales et Appliquées.', 'master, doctorat, PhD, MIAGE, QSE, Petromine', '2026-03-25 20:53:45'),
(6, 'Clubs et Associations', 'Vie Etudiante', 'Présence de clubs spécialisés : Club Géoscience, RobIA Tech, Women Tech.', 'clubs, associations, Geoscience, RobIA Tech, Women Tech, vie etudiante', '2026-03-25 20:53:45'),
(7, 'Administration de la Faculté', 'Administration', 'Le Doyen actuel est le Professeur Marie Joseph Ntamak Nida. L\'université est dirigée par le Recteur, le Professeur Magloire Ondoa.', 'administration, Doyen, Ntamak Nida, Recteur, Magloire Ondoa', '2026-03-25 20:53:45'),
(8, 'Actualités Récentes', 'Actualites', 'En janvier 2026, la faculté a célébré la promotion de nouveaux Maîtres de Conférences et l\'ouverture du laboratoire d\'IA.', 'actualites, janvier 2026, maitre de conferences, laboratoire IA', '2026-03-25 20:53:45'),
(9, 'Localisation des Cours', 'Infrastructures', 'Les cours de Licence 1 et 2 se déroulent principalement au Campus 1 (Ancien de la Cité), tandis que les Masters sont au Campus 3 (Logbessou PK17).', 'localisation, campus 1, campus 3, Logbessou, cours', '2026-03-25 20:53:45'),
(10, 'Bibliothèque Centrale', 'Ressources', 'Située au Campus 1, elle est ouverte de 8h à 18h pour les recherches et la consultation d\'ouvrages scientifiques.', 'bibliotheque, campus 1, horaires, ouvrages, ressources', '2026-03-25 20:53:45'),
(11, 'Assurance Étudiante', 'Sante', 'Chaque étudiant inscrit bénéficie d\'une couverture santé au Centre Médico-Social (CMS) de l\'Université de Douala.', 'assurance, sante, CMS, couverture medicale', '2026-03-25 20:53:45'),
(12, 'La Session Normale (SN)', 'Evaluations', 'C\'est la première phase d\'examens à la fin de chaque semestre (janvier/février pour le S1 et juin/juillet pour le S2). Elle comprend les CC, TPE, TP et l\'examen final.', 'session normale, examens, semestre, CC, TPE, TP', '2026-03-25 20:53:45'),
(13, 'Validation d\'une UE', 'Evaluations', 'Une Unité d\'Enseignement (UE) est validée en session normale si l\'étudiant obtient une moyenne pondérée (CC + TPE + Examen) supérieure ou égale à 10/20.', 'validation, UE, moyenne, 10/20, evaluations', '2026-03-25 20:53:45'),
(14, 'Compensation des Notes', 'Evaluations', 'À la FS, la compensation permet de valider un semestre si la moyenne générale est de 10/20, même avec une note entre 07 et 09/20 dans certaines matières.', 'compensation, semestre, moyenne generale, notes, rachat', '2026-03-25 20:53:45'),
(15, 'La Session de Rattrapage', 'Evaluations', 'Elle concerne les étudiants n\'ayant pas validé une UE en session normale (note < 10/20). Elle a lieu après la publication des notes de la normale.', 'rattrapage, session, echec, evaluations, rattrapage FS', '2026-03-25 20:53:45'),
(16, 'Note Finale après Rattrapage', 'Evaluations', 'En cas de rattrapage, la meilleure note entre la session normale et le rattrapage est conservée pour le calcul de la moyenne finale.', 'note finale, rattrapage, calcul moyenne, evaluations', '2026-03-25 20:53:45');
